/* DNX_REGLER_GRIFF_START
   Regler (input type=range) reagieren nicht ueberall auf Ziehen, weil andere
   DNX-Listener den Mausdruck abfangen. Dieser Griff setzt den Wert direkt aus
   der Zeigerposition - unabhaengig vom Browser-Standardverhalten. */
(function(){
  if(window.__dnxReglerGriff){ return; }
  window.__dnxReglerGriff = true;

  var aktiv = null;

  function wertSetzen(el, clientX){
    if(!el){ return; }
    var r = el.getBoundingClientRect();
    if(!r || r.width < 8){ return; }
    var min = parseFloat(el.min); if(!isFinite(min)){ min = 0; }
    var max = parseFloat(el.max); if(!isFinite(max)){ max = 100; }
    var step = parseFloat(el.step); if(!isFinite(step) || step <= 0){ step = 0; }
    var f = (clientX - r.left) / r.width;
    f = Math.max(0, Math.min(1, f));
    var v = min + f * (max - min);
    if(step > 0){ v = Math.round(v / step) * step; }
    v = Math.max(min, Math.min(max, v));
    el.value = String(v);
    try{ el.dispatchEvent(new Event("input", { bubbles: true })); }catch(e1){}
    try{ el.dispatchEvent(new Event("change", { bubbles: true })); }catch(e2){}
  }

  function istRegler(t){
    if(!(t && t.tagName === "INPUT" && String(t.type).toLowerCase() === "range")){ return false; }
    /* v3.95: Die Regler im Pegel-Fenster haben eigene Rad-Handler mit passenden
       Schritten (Offset wirkt exponentiell als Fensterbreite). Der globale
       Handler laesst sie durch, sonst wird doppelt gezaehlt und der Schritt
       ist je nach Trefferstelle verschieden. */
    if(String(t.id || "").indexOf("dnx-wfpro-") === 0){ return false; }
    return true;
  }

  /* Wichtig: hier wird bewusst NICHT stopPropagation aufgerufen - sonst
     bekommen andere Bedienelemente auf der Seite den Mausdruck nicht mehr und
     ihre eigenen Regler/Drag-Funktionen sterben. */
  /* Bewusst ohne preventDefault: sonst entstehen keine mousedown-Ereignisse
     mehr und fremde Bedienelemente (Drag, Auswahl, alte Maus-Handler der
     Empfaenger-Oberflaeche) reagieren nicht mehr. */
  document.addEventListener("pointerdown", function(e){
    if(!istRegler(e.target)){ return; }
    aktiv = e.target;
    wertSetzen(aktiv, e.clientX);
  }, true);

  document.addEventListener("mousedown", function(e){
    if(!istRegler(e.target)){ return; }
    aktiv = e.target;
    wertSetzen(aktiv, e.clientX);
  }, true);

  document.addEventListener("pointermove", function(e){
    if(!aktiv){ return; }
    wertSetzen(aktiv, e.clientX);
  }, true);

  document.addEventListener("mousemove", function(e){
    if(!aktiv){ return; }
    wertSetzen(aktiv, e.clientX);
  }, true);

  function los(){ aktiv = null; }
  document.addEventListener("pointerup", los, true);
  document.addEventListener("mouseup", los, true);
  document.addEventListener("pointercancel", los, true);

  /* Mausrad: EIN Handler ganz aussen am Fenster. Er laeuft vor allen anderen
     Listenern (auch vor fremden, die Ereignisse abfangen) und blockiert sie
     nicht - deshalb funktionieren alle uebrigen Einstellungen unveraendert. */
  function radSchritt(el, e){
    if(!el){ return false; }
    var min = parseFloat(el.min), max = parseFloat(el.max);
    if(!isFinite(min)){ min = 0; } if(!isFinite(max)){ max = 100; }
    var stufe = parseFloat(el.step); if(!isFinite(stufe) || stufe <= 0){ stufe = (max - min) / 100; }
    var schritt = Math.max(stufe * 5, (max - min) / 20);
    if(e && e.shiftKey){ schritt = stufe; }
    /* v3.94: Offset im Pegel-Fenster ist die Fensterbreite und wirkt
       exponentiell: Breite = 16 dB x 2^((28-Regler)/12). Der Standardschritt
       von 3,2 Einheiten verschiebt die Breite um rund 20 % - zum Einstellen
       viel zu grob. Hier einheitlich 0,5 wie auf der Reglerflaeche (etwa 3 %). */
    /* v6.11: SDR# Range/Offset im Pegel-BLOCK des Stylers - 2 dB je Rad (Umschalt 0,5 dB). */
    if (el.id === "dnx-sty-pegel-range" || el.id === "dnx-sty-pegel-offset") { schritt = e && e.shiftKey ? 0.5 : 2; }
    /* v6.11: SDR# Contrast / Range / Offset laufen alle aufwaerts (Rad hoch = Wert hoch). */
    var umgekehrt = false;
    var richtung = ((e && e.deltaY > 0) ? -1 : 1) * (umgekehrt ? -1 : 1);
    var v = parseFloat(el.value) + richtung * schritt;
    if(stufe > 0){ v = Math.round(v / stufe) * stufe; }
    v = Math.max(min, Math.min(max, v));
    if(String(v) === String(el.value)){ return false; }
    el.value = String(v);
    try{ el.dispatchEvent(new Event("input", { bubbles: true })); }catch(e1){}
    try{ el.dispatchEvent(new Event("change", { bubbles: true })); }catch(e2){}
    /* v3.99: Die Pegel-Regler senden hier unmittelbar selbst.
       Gemessen: input-Ereignisse kommen auf dieser Seite nirgendwo an - nicht
       am Element, nicht am Feld, nicht am Dokument, auch nicht in der
       Capture-Phase. Wer nur auf Ereignisse hoert, hoert nichts. */
    try{
      if(window.__dnxStyPegel && String(el.id || "").indexOf("dnx-sty-pegel-") === 0){
        window.__dnxStyPegel(el.id, parseFloat(el.value));
      }
    }catch(e3){}
    return true;
  }
  /* Merker fuer andere DNX-Teile: "der Rad-Griff ist global da" */
  try{ window.__dnxRadWheel = true; }catch(eM){}
  function einhaengen(el){
    /* nur markieren: das 3D-Tool hat einen eigenen Document-Handler, der sich
       damit zurueckhaelt (sonst doppelter Schritt) */
    if(!el || el.__dnxRad){ return; }
    el.__dnxRad = 1;
  }
  window.addEventListener("wheel", function(e){
    if(!istRegler(e.target)){ return; }
    var geaendert = radSchritt(e.target, e);
    if(geaendert){ try{ e.preventDefault(); }catch(e3){} }
  }, { capture: true, passive: false });
  function alleEinhaengen(){
    var l = document.querySelectorAll('input[type=range]');
    for(var i = 0; i < l.length; i++){ einhaengen(l[i]); }
  }
  alleEinhaengen();
  setInterval(function(){ try{ alleEinhaengen(); }catch(e){} }, 1200);
  document.addEventListener("pointerdown", function(e){ einhaengen(e.target); }, true);
  document.addEventListener("mouseover", function(e){ einhaengen(e.target); }, true);
})();
/* DNX_REGLER_GRIFF_END */

/* DNX_MASTER_TOOL_ROW_START */
(function(){
  "use strict";

  if(window.__dnxMasterToolRow) return;
  window.__dnxMasterToolRow=true;

  var ROW_ID="dnx-master-tool-row";

  var TOOLS=[
    {
      id:"dnx-master-yellow",
      label:"Gelb Hover",
      color:"#1f8f52",
      textColor:"#f2fff8",
      original:"dnx-btn-yellow-line",
      state:function(){
        return !!window.__dnxYellowEnabled;
      }
    },
    {
      id:"dnx-master-green",
      label:"Gruen Tuning",
      color:"#1f8f52",
      textColor:"#f2fff8",
      original:"dnx-btn-green-line",
      state:function(){
        return !!window.__dnxGreenEnabled;
      }
    },
    {
      id:"dnx-master-status",
      label:"DNX Status",
      color:"#1f8f52",
      textColor:"#f2fff8",
      original:"dnx-btn-status-toggle",
      state:function(){
        var element=document.getElementById(
          "dnx-live-status"
        );

        return visible(element);
      }
    },
    {
      id:"dnx-master-3d",
      label:"3D Tool",
      color:"#1f8f52",
      textColor:"#f2fff8",
      original:"dnx-btn-3d-tool-toggle",
      state:function(){
        return visible(
          document.getElementById("dnx-3d-win") ||
          document.getElementById(
            "dnx-3dtool-window"
          )
        );
      }
    },
    {
      id:"dnx-master-photo",
      label:"noVNC / Foto",
      color:"#1f8f52",
      textColor:"#f2fff8",
      original:"dnx-photo-desc-toggle-btn",
      state:function(){
        var element=document.querySelector(
          ".openwebrx-description-container"
        );

        return !!(
          visible(element) &&
          element.classList.contains("expanded")
        );
      }
    },
    {
      id:"dnx-master-remote",
      label:"Remote VIEW",
      color:"#1f8f52",
      textColor:"#f2fff8",
      original:"dnx-remote-view-btn",
      state:function(){
        return visible(
          document.getElementById(
            "dnx-source-panel"
          )
        );
      }
    }
  ];

  function visible(element){
    if(!element) return false;

    var style=getComputedStyle(element);

    return (
      style.display!=="none" &&
      style.visibility!=="hidden" &&
      style.opacity!=="0"
    );
  }

  function installStyle(){
    if(
      document.getElementById(
        "dnx-master-tool-row-style"
      )
    ) return;

    var style=document.createElement("style");
    style.id="dnx-master-tool-row-style";

    style.textContent=`
      /*
       * Technische Originalzeile vollständig aus dem Layout
       * entfernen. Originalschalter bleiben per JavaScript
       * anklickbar.
       */
      #dnx-line-toggle-box{
        position:absolute !important;
        left:-100000px !important;
        top:-100000px !important;
        display:block !important;
        width:1px !important;
        height:1px !important;
        min-width:0 !important;
        min-height:0 !important;
        max-width:1px !important;
        max-height:1px !important;
        padding:0 !important;
        margin:0 !important;
        overflow:hidden !important;
        opacity:0 !important;
        visibility:hidden !important;
        pointer-events:none !important;
      }

      #dnx-master-tool-row{
        display:grid !important;
        grid-template-columns:
          repeat(
            auto-fit,
            minmax(108px,1fr)
          ) !important;
        gap:6px !important;
        width:100% !important;
        min-width:0 !important;
        padding:0 !important;
        margin:6px 0 8px !important;
        box-sizing:border-box !important;
        contain:layout !important;
      }

      #dnx-master-tool-row > button{
        position:relative !important;
        inset:auto !important;
        display:flex !important;
        align-items:center !important;
        justify-content:center !important;
        width:100% !important;
        min-width:0 !important;
        max-width:none !important;
        height:28px !important;
        padding:0 5px !important;
        margin:0 !important;
        border:1px solid #fff !important;
        border-radius:999px !important;
        color:#fff !important;
        font:700 11px/1 Segoe UI,sans-serif !important;
        white-space:nowrap !important;
        overflow:hidden !important;
        text-overflow:ellipsis !important;
        cursor:pointer !important;
        opacity:1 !important;
        filter:none !important;
        transform:none !important;
        transition:none !important;
        animation:none !important;
        box-shadow:none !important;
      }

      #dnx-master-remote{
        grid-column:auto !important;
        min-width:0 !important;
      }

      #dnx-master-tool-row > button::before,
      #dnx-master-tool-row > button::after{
        display:none !important;
        content:none !important;
        animation:none !important;
      }

      @media(max-width:430px){
        #dnx-master-tool-row{
          grid-template-columns:
            repeat(2,minmax(0,1fr))
            !important;
        }
      }

      @media(max-width:260px){
        #dnx-master-tool-row{
          grid-template-columns:
            1fr !important;
        }
      }
    `;

    document.head.appendChild(style);
  }

  function getReceiver(){
    return document.getElementById(
      "openwebrx-panel-receiver"
    );
  }

  function createRow(){
    var receiver=getReceiver();

    if(!receiver) return null;

    var row=document.getElementById(ROW_ID);

    if(row) return row;

    row=document.createElement("div");
    row.id=ROW_ID;

    /*
     * Direkt vor Gelb/Grün beziehungsweise vor der
     * Frequenzanzeige einsetzen.
     */
    var frequency=
      receiver.querySelector(
        ".webrx-actual-freq-holder"
      ) ||
      receiver.querySelector(
        ".webrx-actual-freq"
      );

    var anchor=frequency;

    while(
      anchor &&
      anchor.parentNode &&
      anchor.parentNode!==receiver
    ){
      anchor=anchor.parentNode;
    }

    /* DNX v-sichtbar: Leiste IMMER an den Anfang des Empfaengerfelds.
       Sonst landet sie hinter der Frequenzanzeige weit unten und wird
       vom Overlay (overflow:hidden) abgeschnitten -> kein Knopf klickbar. */
    receiver.insertBefore(
      row,
      receiver.firstChild
    );

    TOOLS.forEach(function(tool){
      var button=document.createElement("button");
      button.id=tool.id;
      button.type="button";

      button.addEventListener(
        "click",
        function(event){
          event.preventDefault();
          event.stopPropagation();

          var original=document.getElementById(
            tool.original
          );

          if(original){
            original.click();
          }

          window.setTimeout(paint,80);
          window.setTimeout(paint,300);
        }
      );

      row.appendChild(button);
    });

    return row;
  }

  function paint(){
    installStyle();

    var row=createRow();

    if(!row) return;

    TOOLS.forEach(function(tool){
      var button=document.getElementById(
        tool.id
      );

      if(!button) return;

      var active=false;

      try{
        active=!!tool.state();
      }catch(error){}

      button.textContent=
        tool.label +
        ": " +
        (active ? "On" : "Off");

      button.style.setProperty(
        "background",
        active ? tool.color : "#666666",
        "important"
      );

      button.style.setProperty(
        "color",
        active ? tool.textColor : "#ffffff",
        "important"
      );

      button.style.setProperty(
        "animation",
        "none",
        "important"
      );

      button.style.setProperty(
        "transition",
        "none",
        "important"
      );

      button.style.setProperty(
        "transform",
        "none",
        "important"
      );

      button.style.setProperty(
        "filter",
        "none",
        "important"
      );

      try{
        button.getAnimations().forEach(
          function(animation){
            animation.cancel();
          }
        );
      }catch(error){}
    });
  }

  function boot(){
    installStyle();
    paint();

    /*
     * Nur Farben/Text aktualisieren.
     * Keine Elemente verschieben oder neu erzeugen.
     */
    setInterval(paint,500);
  }

  if(document.readyState==="loading"){
    document.addEventListener(
      "DOMContentLoaded",
      boot,
      {once:true}
    );
  }else{
    boot();
  }

  window.addEventListener("load",paint);
})();
/* DNX_MASTER_TOOL_ROW_END */


  /* DNX_TOP_TICKER_OFF_START: obere Laufzeile per Styler-CSS ausblenden */
  (function(){
    var ID = "dnx-top-ticker-off-style";
    function install(){
      try{
        if(document.getElementById(ID) || !document.head){ return; }
        var st = document.createElement("style");
        st.id = ID;
        st.textContent = "#dnx-ticker-stack{display:none !important;}";
        document.head.appendChild(st);
      }catch(e){}
    }
    install();
    if(document.readyState === "loading"){
      document.addEventListener("DOMContentLoaded", install, {once:true});
    }
  })();
  /* DNX_TOP_TICKER_OFF_END */

