  var DNX_BG_ID = "dnx-freq-grund";
  function dnxBgSetzen(){
    /* v3.108: Malt unsere eigene Zeichenroutine (dnxSpekMal), dann darf diese
       Funktion den Container-Hintergrund NICHT mehr setzen. Zwei Timer
       arbeiteten hier gegeneinander: anwenden() loescht ueber hgAnwenden()
       alle 900 ms die Hintergrund-Eigenschaften (wenn im Styler
       "Spektrum-Hintergrund = Standard" steht), unsere Wache setzt sie
       700 ms spaeter wieder - abwechselnd. Das war das Blinken in der Leiste
       zwischen Spektrum und Bandplan. Der Grund wird jetzt in die
       Zeichenflaeche gemalt; der Container bleibt unangetastet. */
    if(window.__dnxSpekEigen){
      var altBlatt = document.getElementById(DNX_BG_ID);
      if(altBlatt && altBlatt.parentNode){ altBlatt.parentNode.removeChild(altBlatt); }
      return;
    }
    try{
      var id = String(dnxFftId());
      var farbe = (id.indexOf("pal:") === 0) ? DNX_FFT_BG[id.slice(4)] : "";
      var e = document.getElementById(DNX_BG_ID);
      if(!farbe){ if(e){ e.textContent = ""; } return; }
      /* v3.101: Nicht ueber ein Stylesheet. Gemessen: KEINE Regel - auch die
         nackte nicht - setzt sich gegen den vorhandenen Farbverlauf durch.
         Darum unmittelbar am Element mit !important; das gewinnt immer. */
      var ziel = document.getElementById("openwebrx-frequency-container");
      if(ziel){
        try{
          ziel.style.setProperty("background", farbe, "important");
          ziel.style.setProperty("background-image", "none", "important");
          ziel.style.setProperty("background-color", farbe, "important");
        }catch(x2){}
      }
      /* zusaetzlich das alte Blatt weiterpflegen, damit beim Wechsel auf eine
         Palette ohne Grund wieder sauber aufgeraeumt wird */
      if(!e){
        e = document.createElement("style");
        e.id = DNX_BG_ID;
        (document.body || document.head || document.documentElement).appendChild(e);
      }
      var css = "html body #openwebrx-frequency-container{background:" + farbe + " !important;" +
                "background-image:none !important}";
      if(e.textContent !== css){ e.textContent = css; }
    }catch(x){}
  }
