  function dnxWfApply(id){
    if(!dnxWfOk(id)){ id = "default"; }
    if(!dnxWfReg()){ dnxWfState(); return false; }
    try{
      UI.setWfTheme(id);
      /* v6.16: UI.setWfTheme ignoriert stillschweigend jeden Namen, den der
         Empfaenger nicht in seiner Liste hat - dann war die Wahl im Styler
         wirkungslos. Also nachpruefen und die Farben selbst setzen. */
      try{
        if(window.UI && UI.wfTheme !== id && DNX_WF[id] && window.Waterfall && Waterfall.setTheme){
          if(!UI.wfThemes[id]){ UI.wfThemes[id] = DNX_WF[id]; }
          UI.wfTheme = null;
          UI.setWfTheme(id);
          if(UI.wfTheme !== id){ Waterfall.setTheme(DNX_WF[id]); UI.wfTheme = id; }
        }
      }catch(eF){
        try{ Waterfall.setTheme(DNX_WF[id]); }catch(eF2){}
      }
      var lb = document.getElementById("openwebrx-wf-themes-listbox");
      if(lb){ lb.value = id; }
      dnxWfState();
      /* v6.16: sichtbares Bild sofort umfaerben (sonst ~20 s bis zur neuen Farbe) */
      try{ dnxWfNeuMalen("wf:" + id); }catch(eR){}
      return true;
    }catch(e2){ dnxWfState(); return false; }
  }

  /* ---- v6.16: Wasserfall-Sofort-Neumalen ---------------------------------
     Der Kern malt pro Bild genau EINE Zeile (1 px hoch) in ein sehr breites
     Canvas und braucht fuer ein volles Bild gut 20 s. Eine neue Palette war
     deshalb erst viel spaeter zu sehen - der Eindruck war "geht nicht".
     Hier wird deshalb jede gezeichnete Zeile gemerkt (in 256 Stufen zwischen
     den damaligen Pegeln) und das sichtbare Bild nach jeder Wahl SOFORT mit
     der dann aktuellen Palette neu gemalt. */
  var WFH = { w: 0, cap: 420, n: 0, zeilen: [], db: [], min: [], max: [], ziel: [], an: 0, gemeldet: 0 };
  function wfhMerken(data, mn, mx, cv, y){
    var w = data.length, i, v, dv, sp = (mx - mn) || 1;
    if(w !== WFH.w){
      WFH.w = w; WFH.zeilen = []; WFH.db = []; WFH.min = []; WFH.max = []; WFH.ziel = []; WFH.n = 0;
    }
    var k = WFH.n % WFH.cap;
    var buf = WFH.zeilen[k];
    if(!buf || buf.length !== w){ buf = new Uint8Array(w); }
    var dbBuf = WFH.db[k];
    if(!dbBuf || dbBuf.length !== w){ dbBuf = new Int16Array(w); }
    for(i = 0; i < w; i++){
      dv = data[i];
      v = (dv - mn) / sp;
      buf[i] = v < 0 ? 0 : (v > 1 ? 255 : (v * 255 + 0.5) | 0);
      var q = Math.round((isFinite(dv) ? dv : -150) * 20);
      dbBuf[i] = q < -32768 ? -32768 : (q > 32767 ? 32767 : q);
    }
    WFH.zeilen[k] = buf; WFH.db[k] = dbBuf; WFH.min[k] = mn; WFH.max[k] = mx;
    WFH.ziel[k] = (cv && cv.width >= w && y >= 0 && y < cv.height) ? { cv: cv, y: y } : null;
    WFH.n++;
  }
  function dnxWfNeuMalen(grund){
    try{
      var wf = window.Waterfall;
      if(!WFH.n || !wf || !WFH.w || !wf.colors || wf.colors.length < 2){ return 0; }
      var t0 = (window.performance && performance.now) ? performance.now() : Date.now();
      var CL = wf.colors.length, lut = new Uint32Array(CL), i, c, r, g2, b;
      for(i = 0; i < CL; i++){
        c = wf.colors[i];
        if(typeof c === "number"){ r = (c >> 16) & 255; g2 = (c >> 8) & 255; b = c & 255; }
        else if(c && typeof c.length === "number"){ r = c[0] | 0; g2 = c[1] | 0; b = c[2] | 0; }
        else { r = g2 = b = 0; }
        lut[i] = 0xFF000000 | (b << 16) | (g2 << 8) | r;
      }
      var lv = wf.levels;
      var hasLv = (lv && isFinite(lv.min) && isFinite(lv.max) && lv.max > lv.min);
      var lvMin = hasLv ? lv.min : 0;
      var lvInv = hasLv ? ((CL - 1) / (lv.max - lv.min)) : 0;
      var maxIdx = CL - 1;
      var total = Math.min(WFH.n, WFH.cap), start = WFH.n - total, anzahl = 0;
      var cur = null, ctx = null, img = null, out = null;
      var fk = (CL - 1) / 255;
      for(var j = 0; j < total; j++){
        var k = (start + j) % WFH.cap, z = WFH.ziel[k];
        if(!z || !z.cv || !z.cv.parentNode){ continue; }
        if(z.cv !== cur){
          cur = z.cv; ctx = null; img = null; out = null;
          try{ ctx = cur.getContext("2d"); }catch(eG){ ctx = null; }
          if(!ctx){ continue; }
          try{ img = ctx.createImageData(WFH.w, 1); }catch(eI){ img = null; }
          if(!img || !img.data){ continue; }
          out = new Uint32Array(img.data.buffer);
        }
        var dbSrc = (hasLv && WFH.db && WFH.db[k]) ? WFH.db[k] : null;
        if(dbSrc){
          for(var xd = 0; xd < WFH.w; xd++){
            var ix = Math.round(((dbSrc[xd] * 0.05) - lvMin) * lvInv);
            out[xd] = lut[ix < 0 ? 0 : (ix > maxIdx ? maxIdx : ix)];
          }
        } else {
          var src = WFH.zeilen[k];
          if(CL === 256){
            for(var x = 0; x < WFH.w; x++){ out[x] = lut[src[x]]; }
          } else {
            for(var x2 = 0; x2 < WFH.w; x2++){ out[x2] = lut[(src[x2] * fk + 0.5) | 0]; }
          }
        }
        ctx.putImageData(img, 0, z.y);
        anzahl++;
      }
      var dauer = Math.round((((window.performance && performance.now) ? performance.now() : Date.now()) - t0) * 10) / 10;
      window.__dnxWfNeuZeit = dauer; window.__dnxWfNeuZeilen = anzahl;
      window.__dnxWfNeuGrund = String(grund || ""); window.__dnxWfNeuBei = WFH.n;
      if(!WFH.gemeldet && anzahl > 0){
        WFH.gemeldet = 1;
        try{ console.info("[DNX-WF] Bild neu gemalt:", anzahl, "Zeilen in", dauer, "ms"); }catch(eC){}
      }
      return anzahl;
    }catch(e){ return -1; }
  }
  function dnxWfVerfolge(){
    if(WFH.an){ return true; }
    if(typeof window.waterfall_add !== "function"){ return false; }
    var alt = window.waterfall_add;
    WFH.an = 1;
    window.waterfall_add = function(data){
      var r = alt.apply(this, arguments);
      try{
        var lv = window.Waterfall && window.Waterfall.levels;
        var cs = window.canvases;
        if(data && data.length && lv && cs && cs.length){
          wfhMerken(data, lv.min, lv.max, cs[cs.length - 1], window.canvas_actual_line);
        }
      }catch(e){}
      return r;
    };
    /* Erhaelt das Kennzeichen des 3D-Hooks, falls er bereits darunter liegt. */
    if(alt.__dnx3d){ window.waterfall_add.__dnx3d = true; }
    try{ window.__dnxWfFolg = 1; }catch(e2){}
    return true;
  }
  try{
    window.dnxWfNeuMalen = dnxWfNeuMalen; window.__dnxWfNeuMalen = dnxWfNeuMalen;
    window.dnxWfVerfolge = dnxWfVerfolge; window.__dnxWfHist = WFH;
  }catch(eX){}
  (function(){
    setInterval(function(){ try{ if(!WFH.an){ dnxWfVerfolge(); } }catch(e){} }, 1200);
  })();
  /* DNX-WF-REPAINT-V616 */
  function dnxFftId(){
    var s = "";
    try{ s = localStorage.getItem(FFT_KEY) || ""; }catch(e){}
    var i;
    if(!s){
      return dnxMsdrParse()[String(DNX_FFT_STD).slice(4)] ? DNX_FFT_STD : "original";
    }
    for(i = 0; i < DNX_FFT.length; i++){ if(DNX_FFT[i][0] === s){ return s; } }
    if(String(s).indexOf("pal:") === 0 && dnxMsdrParse()[String(s).slice(4)]){ return s; }
    /* v3.68: geloeschte Palette -> eingebauter Startwert statt Original-Weiss */
    return dnxMsdrParse()[String(DNX_FFT_STD).slice(4)] ? DNX_FFT_STD : "original";
  }
  function dnxFftName(id){
    var i;
    for(i = 0; i < DNX_FFT.length; i++){ if(DNX_FFT[i][0] === id){ return DNX_FFT[i][1]; } }
    var e = dnxMsdrParse()[String(id).slice(4)];
    if(String(id).indexOf("pal:") === 0 && e){ return "Palette " + e.label; }
    return id;
  }
  function dnxFftFarbe(){
    var id = dnxFftId(), i;
    /* v3.101: Wer in DNX_FFT_PAL eine eigene Spektrum-Farbe stehen hat,
       bekommt sie auch. Bisher diente der Eintrag nur als Merker ("diese
       Palette hat eine eigene Farbe") und verwendet wurde stattdessen die
       Farbe aus der WASSERFALL-Palette - dadurch blieb das Spektrum dunkel. */
    if(String(id).indexOf("pal:") === 0){
      var vorrang = DNX_FFT_PAL[String(id).slice(4)];
      if(vorrang){ return vorrang; }
    }
    if(String(id).indexOf("pal:") === 0){
      var pn = String(id).slice(4);
      if(DNX_WF[pn]){
        var hex = DNX_WF[pn], pos = (hex.length - 1) * 0.8;
        var i0 = Math.floor(pos), i1 = Math.min(hex.length - 1, i0 + 1), tt = pos - i0;
        var a = hex[i0], b2 = hex[i1];
        var r = Math.round((((a >> 16) & 255) * (1 - tt)) + (((b2 >> 16) & 255) * tt));
        var g2 = Math.round((((a >> 8) & 255) * (1 - tt)) + (((b2 >> 8) & 255) * tt));
        var bl = Math.round(((a & 255) * (1 - tt)) + ((b2 & 255) * tt));
        return "rgba(" + r + ", " + g2 + ", " + bl + ", 0.62)";
      }
    }
    for(i = 0; i < DNX_FFT.length; i++){ if(DNX_FFT[i][0] === id){ return (id === "original") ? DNX_FFT_ALT : DNX_FFT[i][1]; } }
    var e = dnxMsdrParse()[String(id).slice(4)];
    if(String(id).indexOf("pal:") === 0 && e){
      var sp = DNX_FFT_PAL[String(id).slice(4)];
      if(sp){ return sp; }
      return dnxMsdrCss(dnxMsdrRgb(e.stops, 0.8));
    }
    return DNX_FFT_ALT;
  }
  function dnxFftGrad(c){
    var id = dnxFftId();
    if(String(id).indexOf("pal:") !== 0){ return null; }
    var e = dnxMsdrParse()[String(id).slice(4)];
    if(!e || !c || typeof c.createLinearGradient !== "function"){ return null; }
    var h = (c.canvas && c.canvas.height) ? c.canvas.height : 100;
    if(!h){ h = 100; }
    var gr = c.createLinearGradient(0, 0, 0, h);
    gr.addColorStop(0, dnxMsdrCss(dnxMsdrRgb(e.stops, 1)));
    gr.addColorStop(0.5, dnxMsdrCss(dnxMsdrRgb(e.stops, 0.55)));
    gr.addColorStop(1, dnxMsdrCss(dnxMsdrRgb(e.stops, 0.05)));
    return gr;
  }
  function dnxFftZiel(c){
    /* v3.66: NUR fuer Paletten mit eigener Spektrum-Farbe (2511) hat diese Vorrang
       vor dem Verlauf - alle anderen Paletten bleiben unveraendert. */
    var _f = dnxFftFarbe(), _id = String(dnxFftId()).slice(4);
    if(DNX_FFT_PAL[_id] && _f){ return _f; }
    var g = dnxFftGrad(c);
    if(g){ return g; }
    return _f || DNX_FFT_ALT;
  }
  /* v3.102: Eigene Zeichenroutine fuer das Spektrum.
     Warum: der Core (lib/Spectrum.js) setzt die Fuellfarbe nur EINMAL beim
     Anlegen des Kontexts, leert die Flaeche jeden Frame auf TRANSPARENT und
     gibt jedem Balken dieselbe Farbe, egal wie hoch er ist. Der dunkle
     Untergrund kommt aus dem Eltern-Container, den keine CSS-Regel
     ueberschreiben kann. Beides ist hier behoben. */
  function dnxSpekFarben(pn){
    var r = DNX_FFT_SPEK[pn];
    if(r){ return r; }
    return [DNX_FFT_BG[pn] || "#0a0a14", "#2a4a8c", "#8a8adf", "#e8ecff"];
  }

  function dnxSpekModus(){
    if(typeof window.__dnxSpecSkala === "function"){
      try{ return window.__dnxSpecSkala() === "pegel" ? "pegel" : "auto"; }catch(e){}
    }
    try{
      var raw = localStorage.getItem("dnx.spectrum.darstellung.v2");
      if(raw){
        var o = JSON.parse(raw);
        if(o && o.skala === "auto"){ return "auto"; }
      }
    }catch(e2){}
    return "pegel";
  }

  function dnxSpekPegelBereich(){
    try{
      if(typeof window.__dnxPegelLesen === "function"){
        var pl = window.__dnxPegelLesen();
        if(pl && isFinite(pl.boden) && isFinite(pl.deckel) && pl.deckel > pl.boden){
          return { min: Number(pl.boden), max: Number(pl.deckel) };
        }
      }
    }catch(e){}
    try{
      var raw = localStorage.getItem("dnx.wfpro.state.v3");
      if(raw){
        var s = JSON.parse(raw);
        if(s && isFinite(s.lo) && isFinite(s.hi) && s.hi > s.lo){
          return { min: Number(s.lo), max: Number(s.hi) };
        }
      }
    }catch(e2){}
    return { min: -78.0, max: -58.0 };
  }

  function dnxSpekSkala(sv, s0, s1){
    try{
      if(!sv){ return null; }
      if(dnxSpekModus() === "pegel"){
        var pb = dnxSpekPegelBereich();
        if(pb){
          sv.min = pb.min;
          sv.max = pb.max;
          var resPeg = { min: pb.min, max: pb.max, p50: pb.min, p995: pb.max, pegel: 1 };
          sv.__dnxSkala = resPeg;
          sv.__dnxSkalaTs = Date.now();
          return resPeg;
        }
      }
      if(!sv.data || !sv.data.length){ return null; }
      var n = sv.data.length;
      if(!(s0 >= 0)){ s0 = 0; }
      if(!(s1 > s0) || s1 > n){ s1 = n; }
      var spanN = s1 - s0;
      if(spanN < 4){ return null; }
      var jetzt = Date.now();
      var sig = String(typeof center_freq !== "undefined" ? center_freq : 0) + "|" +
                String(typeof bandwidth !== "undefined" ? bandwidth : 0) + "|" +
                String(s0) + "|" + String(s1);
      if(sv.__dnxSkala && !sv.__dnxSkala.pegel && sv.__dnxSkalaSig === sig && (jetzt - (sv.__dnxSkalaTs || 0)) < 75){
        sv.min = sv.__dnxSkala.min;
        sv.max = sv.__dnxSkala.max;
        return sv.__dnxSkala;
      }
      var a0 = Math.max(s0, Math.floor(n * 0.10)), a1 = Math.min(s1, Math.ceil(n * 0.90));
      if(a1 - a0 < 24){ a0 = s0; a1 = s1; }
      var step = Math.max(1, Math.floor((a1 - a0) / 600));
      var vlo = 1e9, vhi = -1e9, cnt = 0, i, v;
      for(i = a0; i < a1; i += step){
        v = sv.data[i];
        if(typeof v === "number" && isFinite(v)){
          if(v < vlo){ vlo = v; }
          if(v > vhi){ vhi = v; }
          cnt++;
        }
      }
      if(cnt < 4 || !(vhi > vlo)){ return sv.__dnxSkala || null; }
      var NB = 256, bins = new Uint16Array(NB), bw = (vhi - vlo) / NB, tot = 0;
      for(i = a0; i < a1; i += step){
        v = sv.data[i];
        if(typeof v === "number" && isFinite(v)){
          bins[Math.min(NB - 1, Math.floor((v - vlo) / bw))]++;
          tot++;
        }
      }
      function q(p){
        var target = p * tot, acc = 0, k;
        for(k = 0; k < NB; k++){
          acc += bins[k];
          if(acc >= target){ return vlo + (k + 0.5) * bw; }
        }
        return vhi;
      }
      var p50 = q(0.50);
      var p995 = q(0.995);
      var dyn = Math.max(5, Math.min(35, p995 - p50));
      var zielSpan = Math.max(16, Math.min(40, dyn + 10));
      var zielMin = p50 - zielSpan * 0.18;
      var zielMax = zielMin + zielSpan;

      var reset = (!sv.__dnxSkala || sv.__dnxSkalaSig !== sig);
      var warm = reset ? 0 : (sv.__dnxSkalaWarm || 0);
      var tau = reset ? 1.0 : (warm < 8 ? 0.35 : 0.06);
      var sMin = reset ? zielMin : (sv.__dnxSkala.min + (zielMin - sv.__dnxSkala.min) * tau);
      var sMax = reset ? zielMax : (sv.__dnxSkala.max + (zielMax - sv.__dnxSkala.max) * tau);
      var res = { min: sMin, max: sMax, p50: p50, p995: p995 };
      sv.__dnxSkala = res;
      sv.__dnxSkalaSig = sig;
      sv.__dnxSkalaWarm = warm + 1;
      sv.__dnxSkalaTs = jetzt;
      sv.min = sMin;
      sv.max = sMax;
      return res;
    }catch(e){ return null; }
  }

  function dnxSpekMal(sv){
    var pn = String(dnxFftId()).slice(4);
    var el = sv.el;
    if(!el || !(el.clientHeight > 0)){ return; }

    /* Kontext aufbauen - dieser Teil steht im Core mitten in draw() und
       muss hier nachgebildet werden, sonst gibt es keine Zeichenflaeche. */
    var w = el.offsetWidth, h = el.offsetHeight;
    if(!(w > 0) || !(h > 0)){ return; }
    if(!sv.ctx || w != el.width || h != el.height){
      el.width = w; el.height = h;
      sv.ctx = el.getContext("2d");
    }
    var ctx = sv.ctx;
    if(!ctx){ return; }
    w = el.width; h = el.height;

    var farben = dnxSpekFarben(pn);

    /* Grund - selbst gemalt, damit er unabhaengig vom Container sitzt.
       v3.106: als flacher Verlauf von unten nach oben. */
    var hg = DNX_FFT_HG[pn] || [farben[0], farben[0], null];
    var hgRaster = (hg.length >= 4) ? hg[3] : hg[2];
    ctx.clearRect(0, 0, w, h);
    if(hg.length >= 4 && hg[0] && hg[1] && hg[2]){
      var gh = ctx.createLinearGradient(0, h, 0, 0);
      gh.addColorStop(0, hg[0]);
      gh.addColorStop(0.5, hg[1]);
      gh.addColorStop(1, hg[2]);
      ctx.fillStyle = gh;
    }else if(hg[0] && hg[1] && hg[0] !== hg[1]){
      var gh2 = ctx.createLinearGradient(0, h, 0, 0);
      gh2.addColorStop(0, hg[0]);
      gh2.addColorStop(1, hg[1]);
      ctx.fillStyle = gh2;
    }else{
      ctx.fillStyle = hg[0] || farben[0];
    }
    ctx.fillRect(0, 0, w, h);

    /* v3.110: Glow-Flaeche. Die Balken kommen auf eine eigene transparente
       Leinwand, damit NUR sie weichgezeichnet werden - nicht der Grund und
       nicht das dB-Raster. */
    /* v3.116: unser Grund, damit die Leiste denselben Ton bekommen kann
       (siehe hgAnwenden). Oben liegt die Farbe, die auch im Streifen
       oberhalb des Spektrums gebraucht wird. */
    window.__dnxSpekGrund = (hg.length >= 4) ? (hg[2] || hg[0]) : (hg[0] || farben[0]);
    var glow = DNX_FFT_GLOW[pn];
    var gl = null, glx = null, glb = null, glbx = null;
    if(glow && glow.length >= 3){
      try{
        gl = sv.__dnxGlow;
        if(!gl){ gl = document.createElement("canvas"); sv.__dnxGlow = gl; }
        if(gl.width !== w || gl.height !== h){ gl.width = w; gl.height = h; }
        glx = gl.getContext("2d");
        if(glx){ glx.clearRect(0, 0, w, h); }
        /* zweite Flaeche: hierauf wird der Bloom gerechnet, damit die
           scharfen Balken unberuehrt bleiben */
        glb = sv.__dnxGlowB;
        if(!glb){ glb = document.createElement("canvas"); sv.__dnxGlowB = glb; }
        if(glb.width !== w || glb.height !== h){ glb.width = w; glb.height = h; }
        glbx = glb.getContext("2d");
        if(glbx){ glbx.clearRect(0, 0, w, h); }
      }catch(eG0){ glx = null; glbx = null; }
    }
    var ziel = glx || ctx;

    /* Sichtbarer Bereich und Datenfenster wie im Core */
    var data_start, data_end;
    try{
      var vf = get_visible_freq_range();
      var vs = 0.5 - (center_freq - vf.start) / bandwidth;
      var ve = 0.5 - (center_freq - vf.end) / bandwidth;
      data_start = Math.round(fft_size * vs);
      data_end = Math.round(fft_size * ve);
    }catch(e){ return; }
    var data_width = data_end - data_start;
    if(!(data_width > 0)){ return; }
    /* v6.01: Spektrum-Skala ueber dnxSpekSkala vom Wasserfall entkoppeln:
       Rauschboden (p50) sitzt ruhig bei ~18 % Hoehe, Spitzen (p995) haben
       ausreichend Luft nach oben, und der Farbverlauf geht von p50..p995
       statt von der Passband-Randflanke bis zum DC-Spike. */
    var sk = dnxSpekSkala(sv, data_start, data_end);
    var dmin = sk ? sk.min : sv.min;
    var dmax = sk ? sk.max : sv.max;
    var data_height = Math.abs(dmax - dmin);
    if(!(data_height > 0)){ return; }
    try{
      window.__dnxSpekRasterInfo = { min: dmin, max: dmax, modus: (sk && sk.pegel) ? "pegel" : "auto", ts: Date.now() };
      if(typeof window.__dnxRasterJetzt === "function"){ window.__dnxRasterJetzt(false); }
    }catch(eRi){}
    var yr = h / data_height;

    if(hgRaster && !window.__dnxSpekRasterAn){
      try{
        var abstand = 10 * yr;
        if(abstand >= 7){
          ctx.save();
          ctx.strokeStyle = hgRaster;
          ctx.lineWidth = 1;
          ctx.beginPath();
          var startWert = Math.ceil(dmin / 10) * 10;
          for(var vv2 = startWert; vv2 <= dmax; vv2 += 10){
            var yy2 = h - (vv2 - dmin) * yr;
            if(yy2 < 1 || yy2 > h - 1){ continue; }
            var py = Math.round(yy2) + 0.5;
            ctx.moveTo(0, py);
            ctx.lineTo(w, py);
          }
          ctx.stroke();
          ctx.restore();
        }
      }catch(e6){}
    }

    var lo = (sk && !sk.pegel) ? (sk.p50 - 0.5) : dmin;
    var hi = (sk && !sk.pegel) ? Math.max(sk.p50 + 8.5, Math.min(dmax - 0.5, sk.p995 + 2.5)) : dmax;
    if(!isFinite(lo) || !isFinite(hi) || hi - lo < 2){ lo = dmin; hi = dmax; }
    var yLo = (lo - dmin) * yr, yHi = (hi - dmin) * yr;
    var gUnten = h - Math.max(0, Math.min(h, yLo));
    var gOben  = h - Math.max(0, Math.min(h, yHi));
    /* Mindestspreizung, sonst wird bei ganz flachem Bild alles einfarbig */
    if(gUnten - gOben < h * 0.35){ gOben = Math.max(0, gUnten - h * 0.35); }
    if(gUnten - gOben < 6){ gUnten = h; gOben = 0; }
    var gr = ziel.createLinearGradient(0, gUnten, 0, gOben);
    gr.addColorStop(0.00, farben[1]);
    gr.addColorStop(0.55, farben[2]);
    gr.addColorStop(1.00, farben[3]);
    ziel.fillStyle = gr;

    var x, y, xr;
    if(w <= data_width){
      xr = data_width / w;
      for(x = 0; x < w; x++){
        y = (sv.data[data_start + ((x * xr) | 0)] - dmin) * yr;
        if(y > 0){ ziel.fillRect(x, h, 1, -y); }
      }
    }else{
      xr = w / data_width;
      var xp = 0;
      for(x = 0; x < data_width; x++){
        y = (sv.data[data_start + x] - dmin) * yr;
        var k = ((x + 1) * xr) | 0;
        if(y > 0){ ziel.fillRect(xp, h, k - xp, -y); }
        xp = k;
      }
    }

    /* v3.110: Glow - weich und additiv DARUNTER, scharf DARUEBER. */
    if(glx && glbx){
      /* 1) Bloom auf der ZWEITEN Flaeche: helle Spitzen additiv verstaerken,
            dunkles Rauschen bleibt dunkel. Die scharfen Balken in gl bleiben
            dabei unberuehrt - das ist der Unterschied zu v3.111. */
      try{
        glbx.clearRect(0, 0, w, h);
        glbx.globalCompositeOperation = "source-over";
        glbx.drawImage(gl, 0, 0);
        var boost = glow[0] || 1;
        glbx.globalCompositeOperation = "lighter";
        for(var gb = 0; gb < boost; gb++){ glbx.drawImage(glb, 0, 0); }
        glbx.globalCompositeOperation = "source-over";
      }catch(eB){}
      /* 2) v3.112: der Schein kommt UNTER die Balken. Lag er darueber, wurden
         die Balken mit aufgehellt und brannten ins Weiss aus (gemessen: 1241
         von 18000 Pixeln weiss). Jetzt strahlt nur der dunkle Grund. */
      try{
        for(var gs = 1; (gs + 1) < glow.length; gs += 2){
          var gb2 = glow[gs], ga2 = glow[gs + 1];
          if(!(gb2 > 0) || !(ga2 > 0)){ continue; }
          ctx.save();
          /* v3.115: ENTSCHEIDUNG - "screen", nicht "lighter".
             Gemessener Vergleich auf dem farbigen Grund:
               screen  -> Schein +5.8, Reichweite 10 px,  92/18000 weiss
               lighter -> Schein +4.6, Reichweite 10 px, 373/18000 weiss
             Additiv bringt also KEINEN staerkeren Schein (der Grund ist schon
             heller, es fehlt der Abstand zur Saettigung), brennt aber vier Mal
             so viele Pixel aus. "screen" ist hier die bessere Wahl.
             Der Schein liegt seit v3.112 UNTER den Balken - die werden danach
             deckend darueber gemalt und behalten ihre Farbe. */
          ctx.globalCompositeOperation = "screen";
          ctx.filter = "blur(" + gb2 + "px)";
          ctx.globalAlpha = ga2;
          ctx.drawImage(glb, 0, 0);
          ctx.restore();
        }
      }catch(eG1){}
      /* 3) scharfe, farbige Balken zuletzt darueber */
      try{ ctx.drawImage(gl, 0, 0); }catch(eG2){}
    }

    /* helle Oberkante - laesst Signalspitzen deutlich hervortreten */
    try{
      ctx.strokeStyle = farben[4] || farben[3];
      ctx.lineWidth = 1;
      ctx.beginPath();
      if(w <= data_width){
        xr = data_width / w; yr = h / data_height;
        for(x = 0; x < w; x++){
          y = (sv.data[data_start + ((x * xr) | 0)] - dmin) * yr;
          if(y < 0){ y = 0; } else if(y > h){ y = h; }
          if(x === 0){ ctx.moveTo(x + 0.5, h - y); } else { ctx.lineTo(x + 0.5, h - y); }
        }
      }else{
        xr = w / data_width; yr = h / data_height;
        var xp2 = 0;
        for(x = 0; x < data_width; x++){
          y = (sv.data[data_start + x] - dmin) * yr;
          if(y < 0){ y = 0; } else if(y > h){ y = h; }
          var k2 = ((x + 1) * xr) | 0;
          var xm = (xp2 + k2) / 2;
          if(x === 0){ ctx.moveTo(xm, h - y); } else { ctx.lineTo(xm, h - y); }
          xp2 = k2;
        }
      }
      ctx.stroke();
    }catch(e2){}
  }

  function dnxSpekEigen(){
    var id = String(dnxFftId());
    if(id === "original" || id.indexOf("pal:") !== 0){ return 0; }
    var pn = id.slice(4);
    return (DNX_FFT_SPEK[pn] || DNX_FFT_PAL[pn]) ? 1 : 0;
  }

  function dnxSpekInstall(){
    /* Merker zuerst: der Ueberzug aus v6.19 (spekUeberzug) muss wissen, ob
       wir selbst malen - auch dann, wenn er vor uns eingehakt wurde. */
    window.__dnxSpekEigen = dnxSpekEigen();

    /* WICHTIG: der Styler setzt spectrum.draw als EIGENSCHAFT DES OBJEKTS
       (spekMalHaken), nicht auf dem Prototyp. Der Zeichen-Timer ruft
       me.draw() - also die Objekt-Eigenschaft. Wer nur den Prototyp
       austauscht, wird NIE gerufen (gemessen: 0 Aufrufe in 3 s).
       Darum muss die Instanz selbst abgegriffen werden. */
    try{
      var sp = window.spectrum;
      /* v3.107: Pruefung an der FUNKTION selbst (Marke __dnxSpek), nicht an
         einem Merker am Objekt. Grund: spekMalWeg() setzt sp.draw zurueck,
         sobald die Styler-Palette auf "Original" steht - auch wenn das
         Spektrum auf pal:2411 laeuft. Der alte Merker __dnxSpekDraw blieb
         dann stehen, der Haken wurde nie neu gesetzt: kein Hintergrund,
         kein Raster, und beim Hin- und Hersetzen blinkte es. */
      if(sp && typeof sp.draw === "function" && sp.draw.__dnxSpek !== 1){
        var kette = sp.draw;
        sp.__dnxSpekAlt = kette;
        var meine = function(){
          if(dnxSpekModus() === "pegel"){
            var pb = dnxSpekPegelBereich();
            if(pb){ this.min = pb.min; this.max = pb.max; }
          }
          if(window.__dnxSpekEigen){
            try{ dnxSpekMal(this); return; }
            catch(e){ /* weiter unten faengt die alte Kette auf */ }
          }
          var resK = kette.apply(this, arguments);
          try{
            if(isFinite(this.min) && isFinite(this.max) && this.max > this.min){
              window.__dnxSpekRasterInfo = { min: this.min, max: this.max, modus: dnxSpekModus(), ts: Date.now() };
              if(typeof window.__dnxRasterJetzt === "function"){ window.__dnxRasterJetzt(false); }
            }
          }catch(eRk){}
          return resK;
        };
        meine.__dnxSpek = 1;
        sp.draw = meine;
        /* Damit spekMalWeg() unsere Funktion WIEDER einsetzt statt sie zu
           entfernen - es stellt sp.draw auf __dnxPalDrawAlt zurueck. */
        if(sp.__dnxPalDraw){ sp.__dnxPalDrawAlt = meine; }
      }
    }catch(e4){}

    if(!window.__dnxSpekNeuMalen){
      window.__dnxSpekNeuMalen = function(){
        try{
          var s = window.spectrum;
          if(!s){ return false; }
          s.__dnxSkala = null;
          if(dnxSpekModus() === "pegel"){
            var pb = dnxSpekPegelBereich();
            if(pb){ s.min = pb.min; s.max = pb.max; }
          }
          if(typeof s.draw === "function"){ s.draw(); }
          return true;
        }catch(e){ return false; }
      };
    }

    if(typeof window.Spectrum !== "function"){ return false; }
    if(window.Spectrum.prototype.__dnxAlt){ return true; }
    var alt = window.Spectrum.prototype.draw;
    if(typeof alt !== "function"){ return false; }
    window.Spectrum.prototype.__dnxAlt = alt;
    window.Spectrum.prototype.draw = function(){
      if(dnxSpekModus() === "pegel"){
        var pb = dnxSpekPegelBereich();
        if(pb){ this.min = pb.min; this.max = pb.max; }
      }
      /* bei "original" zeichnet unveraendert der Core */
      if(!window.__dnxSpekEigen){
        var rAlt = alt.apply(this, arguments);
        try{
          if(isFinite(this.min) && isFinite(this.max) && this.max > this.min){
            window.__dnxSpekRasterInfo = { min: this.min, max: this.max, modus: dnxSpekModus(), ts: Date.now() };
            if(typeof window.__dnxRasterJetzt === "function"){ window.__dnxRasterJetzt(false); }
          }
        }catch(eRa){}
        return rAlt;
      }
      try{ dnxSpekMal(this); }
      catch(e){ try{ alt.apply(this, arguments); }catch(e3){} }
    };
    if(!window.Spectrum.prototype.__dnxUpdAlt && typeof window.Spectrum.prototype.update === "function"){
      var updAlt = window.Spectrum.prototype.update;
      window.Spectrum.prototype.__dnxUpdAlt = updAlt;
      window.Spectrum.prototype.update = function(){
        var r = updAlt.apply(this, arguments);
        try{
          var ds = 0, de = this.data ? this.data.length : 0;
          try{
            var vf = get_visible_freq_range();
            var vs = 0.5 - (center_freq - vf.start) / bandwidth;
            var ve = 0.5 - (center_freq - vf.end) / bandwidth;
            ds = Math.max(0, Math.round(fft_size * vs));
            de = Math.min(de, Math.round(fft_size * ve));
          }catch(eVf){}
          dnxSpekSkala(this, ds, de);
        }catch(eSk){}
        return r;
      };
    }
    return true;
  }

  function dnxFftInstall(){
    var c = null;
    try{ c = (window.spectrum && spectrum.ctx) ? spectrum.ctx : null; }catch(e){}
    if(!c){ return false; }
    if(fftCtx === c && c.__dnxFillHook){ return true; }
    var d = null;
    try{ d = Object.getOwnPropertyDescriptor(Object.getPrototypeOf(c), "fillStyle"); }catch(e2){}
    if(!d || !d.set){ return false; }
    try{
      Object.defineProperty(c, "fillStyle", {
        configurable: true,
        get: function(){ return c.__dnxFillRoh; },
        set: function(v){
          c.__dnxFillRoh = v;
          var roh = String(v).replace(/[ \t]/g, "");
          var ziel = v;
          if(dnxFftId() !== "original" && roh === "rgba(255,255,255,0.4)"){
            ziel = dnxFftZiel(c);
          }
          try{ d.set.call(c, ziel); }catch(e3){}
        }
      });
      c.__dnxFillHook = 1;
      fftCtx = c;
    }catch(e4){ return false; }
    return true;
  }
  function dnxFftSetze(){
    if(!fftCtx || !fftCtx.__dnxFillHook){ return false; }
    try{ fftCtx.fillStyle = fftCtx.__dnxFillRoh || DNX_FFT_ALT; }catch(e){ return false; }
    return true;
  }
  function dnxFftApply(){
    dnxBgSetzen();
    if(!dnxFftInstall()){ dnxWfState(); return false; }
    dnxFftSetze();
    dnxWfState();
    return true;
  }
  function dnxWfState(){
    if(!wfEls.state){ return; }
    var txt;
    if(!window.UI || !UI.wfThemes){
      txt = "Wasserfall/Spektrum: hier nicht verfuegbar - Original bleibt";
    } else {
      var fftId = dnxFftId();
      txt = "Wasserfall: " + dnxWfName(dnxWfId()) + " | Spektrum: " + dnxFftName(fftId);
    }
    if(wfEls.state.textContent !== txt){ wfEls.state.textContent = txt; }
  }
  /* v3.70: Wache - zieht Spektrumfarbe und dunklen Grund nach, bis beides sitzt.
     Grund: das Spektrum setzt seine Fuellfarbe nur beim Groessenwechsel; kommt unser
     Haken danach, blieb die Fuellung weiss (genau das war beim Nutzer zu sehen). */
  /* v3.118: Schrift im Bandplan schwarz.
     Der Core setzt im Rahmen der Groessenaenderung fillStyle auf Weiss (#FFFFFF)
     und schreibt damit die Bandnamen (fillText). Die Baender selbst laufen ueber
     strokeStyle, fillStyle wird also ausschliesslich fuer die Schrift benutzt.
     Deshalb wird fillText abgefangen und die Farbe nur fuer diesen Aufruf auf
     Schwarz gesetzt - so bleibt es auch nach jeder Groessenaenderung schwarz. */
  function dnxTextSchwarz(c){
    try{
      if(!c || c.__dnxSchwarz){ return; }
      var schreiben = c.fillText.bind(c);
      c.fillText = function(wort, x, y){
        var alt = c.fillStyle;
        c.fillStyle = "#000000";
        var erg = schreiben(wort, x, y);
        c.fillStyle = alt;
        return erg;
      };
      c.__dnxSchwarz = 1;
    }catch(eT){}
  }

  /* v3.119: S-Meter mit Nadel.
     Der Kern (openwebrx.js) rechnet so:
        logValue = 10 * log10(smeter_level)                    // dB
        levels   = Waterfall.getRange()                        // {min, max}
        anteil   = (logValue - (min-20)) / ((max+20) - (min-20))
        setSmeterRelativeValue(anteil)
     Genau diesen Anteil (0..1) greifen wir ab und schieben die Nadel damit
     ueber die Skala: X0 = Ruhestellung, X1 = rechtes Skalenende. */
  var DNX_SM_FLAECHE = "data:image/png;base64,";
  var DNX_SM_NADEL   = "data:image/png;base64,iVBORw0KGgoAAAANSUhEUgAAAAsAAABCCAYAAACB+yyCAAAATUlEQVR42u3MywnAIBCE4Vlr0G7ScUqziPGSQJBFCIinfy77+tjQFNv97SOifW9lgtdqLvqRDN+S6lO19TMYDAaDwWAwGHwCp7HtbD8AJEwQWvOmt2YAAAAASUVORK5CYII=";
  var DNX_SM_X0 = 32.04;   /* Nadelmitte bei   0 % (Bildspalte, nach dem Beschnitt) */
  var DNX_SM_X1 = 195;      /* Nadelmitte bei 100 % (Bildspalte, nach dem Beschnitt) */
  var DNX_SM_Z  = 5.5;   /* Nadelmitte im Streifen (px)      */

  /* v3.126: mehrere Modell-Varianten. Alle Zifferblaetter sind 238x66 und
     teilen dieselbe Geometrie: Drehpunkt des Zeigers bei (119,112) - also
     UNTERHALB des Bildes, wie beim echten Drehspul-Instrument. Der Zeiger
     wird deshalb in einer 66 px hohen Box abgeschnitten.
     Messung und Funktion sind bei allen Modellen IDENTISCH, nur die Anzeige
     unterscheidet sich: art "bild" = verschobenes Nadelbild (bisher),
     "zeiger" = Zeiger dreht sich, "balken" = LCD-Balken wird gefuellt. */
  var DNX_SM_DPX = 119, DNX_SM_DPY = 112;   /* Drehpunkt */
  var DNX_SM_MODELLE = [
    { id:"neu", name:"smeterneu (bisher)", art:"bild",
      flaeche: DNX_SM_FLAECHE, nadel: DNX_SM_NADEL,
      x0: DNX_SM_X0, x1: DNX_SM_X1, z: DNX_SM_Z },
    /* President George: LCD mit 8 Balken als TREPPE von 1 bis 8 aufsteigend
       (kein Bogen). President George II: 8 Segmente auf einem BOGEN, aussen
       S/RF und innen SWR beziffert. Beleuchtung im Styler umschaltbar. */
    { id:"georg1", name:"LCD-Stufenskala (Treppe 1-8)", art:"lcd", form:"treppe" },
    { id:"georg2", name:"LCD-Bogenskala (klassisch)", art:"lcd", form:"bogen" },
    { id:"alan48", name:"Midland Alan 48 Plus", art:"balken",
      flaeche: "data:image/png;base64,",
      balken: { x:32, y:24, b:163, h:14,
                farbe:"linear-gradient(90deg,#37f5b4 0%,#ffe23d 64%,#ff5a4a 100%)",
                maske:"repeating-linear-gradient(90deg,#000 0 6px,transparent 6px 8px)" } }
  ];
  var DNX_SM_MODELL_KEY = "dnx_styler_smeternadel_modell";
  function dnxSMModellId(){
    var v = "";
    try{ v = String(localStorage.getItem(DNX_SM_MODELL_KEY) || ""); }catch(e){}
    for(var i = 0; i < DNX_SM_MODELLE.length; i++){
      if(DNX_SM_MODELLE[i].id === v) return v;
    }
    return "neu";
  }
  function dnxSMModell(){
    var id = dnxSMModellId();
    for(var i = 0; i < DNX_SM_MODELLE.length; i++){
      if(DNX_SM_MODELLE[i].id === id) return DNX_SM_MODELLE[i];
    }
    return DNX_SM_MODELLE[0];
  }

  /* v3.129: LCD-Messwerk President George / George II.
     George      : 8 Balken als TREPPE von 1 bis 8 aufsteigend, kein Bogen.
     George II   : 8 Segmente auf einem BOGEN, aussen S/RF, innen SWR beziffert.
     Die LCD-Beleuchtung ist im Styler umschaltbar (7 Farben wie beim Original). */
  var DNX_SM_LCD_KEY = "dnx_styler_smeternadel_lcd";
  var DNX_SM_LCD_FARBEN = [
    { id:"orange", name:"Orange (Original)", hex:"#ff8c1a" },
    { id:"gelb",   name:"Gelb",              hex:"#ffe93d" },
    { id:"gruen",  name:"Gruen",             hex:"#3dff7a" },
    { id:"blau",   name:"Blau",              hex:"#3da5ff" },
    { id:"tuerkis",name:"Tuerkis",           hex:"#22e0e0" },
    { id:"rot",    name:"Rot",               hex:"#ff3b30" },
    { id:"weiss",  name:"Weiss",             hex:"#eef4ff" },
    { id:"bernstein",name:"Bernstein",         hex:"#ffb300" },
    { id:"limette", name:"Limette",            hex:"#b6ff2e" },
    { id:"smaragd", name:"Smaragd",            hex:"#00e58a" },
    { id:"himmel",  name:"Himmel",             hex:"#7fb2ff" },
    { id:"petrol",  name:"Petrol",             hex:"#0097a7" },
    { id:"violett", name:"Violett",            hex:"#b46bff" },
    { id:"pink",    name:"Pink",               hex:"#ff5fbf" },
    { id:"magenta", name:"Magenta",            hex:"#ff2f6d" },
    { id:"sonne",   name:"Sonne",              hex:"#fff08a" },
    { id:"eisblau", name:"Eisblau",            hex:"#8fe8ff" }
  ];
  function dnxSMFarbeId(){
    var v = "";
    try{ v = String(localStorage.getItem(DNX_SM_LCD_KEY) || ""); }catch(e){}
    for(var i = 0; i < DNX_SM_LCD_FARBEN.length; i++){
      if(DNX_SM_LCD_FARBEN[i].id === v) return v;
    }
    return "orange";
  }
  function dnxSMFarbe(){
    var id = dnxSMFarbeId();
    for(var i = 0; i < DNX_SM_LCD_FARBEN.length; i++){
      if(DNX_SM_LCD_FARBEN[i].id === id) return DNX_SM_LCD_FARBEN[i];
    }
    return DNX_SM_LCD_FARBEN[0];
  }
  function dnxSMRgba(hex, a){
    var h = String(hex).replace("#", "");
    if(h.length === 3){ h = h[0] + h[0] + h[1] + h[1] + h[2] + h[2]; }
    var n = parseInt(h, 16);
    if(isNaN(n)) n = 0xff8c1a;
    return "rgba(" + ((n >> 16) & 255) + "," + ((n >> 8) & 255) + "," + (n & 255) + "," + a + ")";
  }
  /* Modell UND Farbe bestimmen den Aufbau - beides erzwingt einen Neuaufbau. */
  function dnxSMSignatur(){ return dnxSMModellId() + "|" + dnxSMFarbeId(); }

  var DNX_SM_LCD_GEO = {
    treppe: { n:8, x0:52, balken:17, luecke:4, basis:48, hmin:8, hschritt:3.4, zahlY:49 },
    bogen:  { n:8, polX:116, polY:130, winkel:32, rSeg:108, dick:9,
              rAussen:118, rInnen:92,
              aussen:["1","3","5","7","9","+20","+40"],
              innen:["1","1.5","2","3"] }
  };
  /* Punkt auf dem Bogen: 0 Grad = senkrecht ueber dem Drehpunkt. */
  function dnxSMPol(g, r, grad){
    var a = grad * Math.PI / 180;
    return { x: g.polX + r * Math.sin(a), y: g.polY - r * Math.cos(a) };
  }
  function dnxSMLcdBauen(box, m){
    var hex = dnxSMFarbe().hex;
    var lcd = document.createElement("div");
    lcd.id = "dnx-smeter-lcd";
    lcd.style.setProperty("background-color", "#120c08", "important");
    lcd.style.setProperty("background-image",
      "linear-gradient(180deg," + dnxSMRgba(hex, 0.14) + "," + dnxSMRgba(hex, 0.05) + ")", "important");
    lcd.style.setProperty("box-shadow", "inset 0 0 0 2px #0a0705, inset 0 0 12px rgba(0,0,0,.9), 0 0 9px "
      + dnxSMRgba(hex, 0.22), "important");
    box.appendChild(lcd);
    function el(cls, x, y, w, h){
      var d = document.createElement("div");
      d.className = cls;
      d.style.setProperty("left", x.toFixed(1) + "px", "important");
      d.style.setProperty("top", y.toFixed(1) + "px", "important");
      d.style.setProperty("width", w.toFixed(1) + "px", "important");
      d.style.setProperty("height", h.toFixed(1) + "px", "important");
      d.__dnxAn = 0;
      return d;
    }
    function schriftEl(x, y, w, txt, farbe, cls){
      var d = el(cls || "dnx-sm-zahl", x, y, w, 9);
      d.textContent = txt;
      d.style.setProperty("color", farbe, "important");
      return d;
    }
    var g = DNX_SM_LCD_GEO[m.form];
    var dunkel = dnxSMRgba(hex, 0.13);
    var schrift = dnxSMRgba(hex, 0.85);
    if(m.form === "treppe"){
      lcd.appendChild(schriftEl(8, 7, 40, "S/RF", schrift, "dnx-sm-text"));
      for(var i = 0; i < g.n; i++){
        var hh = g.hmin + i * g.hschritt;
        var bx = g.x0 + i * (g.balken + g.luecke);
        var sg = el("dnx-sm-seg", bx, g.basis - hh, g.balken, hh);
        sg.style.setProperty("background", dunkel, "important");
        lcd.appendChild(sg);
        lcd.appendChild(schriftEl(bx, g.zahlY, g.balken, String(i + 1), schrift));
      }
    }else{
      var w = g.winkel, n = g.n, schritt = 2 * w / n;
      var bogen = g.rSeg * (schritt - 1.6) * Math.PI / 180;
      for(var j = 0; j < n; j++){
        var gr = -w + (j + 0.5) * schritt;
        var p = dnxSMPol(g, g.rSeg, gr);
        var s2 = el("dnx-sm-seg", p.x - bogen / 2, p.y - g.dick / 2, bogen, g.dick);
        s2.style.transform = "rotate(" + gr.toFixed(2) + "deg)";
        s2.style.setProperty("background", dunkel, "important");
        lcd.appendChild(s2);
      }
      function reihe(liste, radius){
        for(var k = 0; k < liste.length; k++){
          var ga = -w + (2 * w) * (liste.length > 1 ? k / (liste.length - 1) : 0.5);
          var pa = dnxSMPol(g, radius, ga);
          var bw = liste[k].length > 2 ? 22 : 10;
          lcd.appendChild(schriftEl(pa.x - bw / 2, pa.y - 4.5, bw, liste[k], schrift));
        }
      }
      reihe(g.aussen, g.rAussen);
      reihe(g.innen, g.rInnen);
      lcd.appendChild(schriftEl(6, 46, 34, "S/RF", schrift, "dnx-sm-text"));
      lcd.appendChild(schriftEl(192, 46, 34, "SWR", schrift, "dnx-sm-text"));
    }
  }

  /* v3.122: an/aus und Verschiebung des Messwerks */
  var DNX_SM_AN  = "dnx_styler_smeternadel";
  var DNX_SM_SX  = "dnx_styler_smeternadel_x";
  var DNX_SM_SY  = "dnx_styler_smeternadel_y";
  function dnxSMLesen(schluessel){
    try{
      var v = parseInt(localStorage.getItem(schluessel), 10);
      return isFinite(v) ? v : 0;
    }catch(e){ return 0; }
  }
  function dnxSMStand(){
    try{ return localStorage.getItem(DNX_SM_AN) !== "0"; }catch(e){ return true; }
  }
  function dnxSMSetzen(an){
    try{ localStorage.setItem(DNX_SM_AN, an ? "1" : "0"); }catch(e){}
    try{ dnxSMKnopfText(); }catch(eK){}
    try{ dnxSMeter(); }catch(eM){}
  }

  /* Knopf in der Werkzeugreihe - genau wie AF / DX / Slots (v3.125) */
  function dnxSMKnopf(){
    try{
      var row = document.getElementById("dnx-master-tool-row");
      var panel = document.getElementById("openwebrx-panel-receiver");
      if(!row && !panel) return;
      var b = document.getElementById("dnx-master-smeternadel");
      var frisch = false;
      if(!b){
        b = document.createElement("button");
        b.type = "button";
        b.id = "dnx-master-smeternadel";
        /* Kein eigenes Aussehen und keine eigenen Masse: die Werkzeugreihe
           gibt Form, Schrift und Farbe vor (137x28, Pille, 11px). */
        b.addEventListener("click", function(ev){
          if(ev && ev.preventDefault){ ev.preventDefault(); }
          if(ev && ev.stopPropagation){ ev.stopPropagation(); }
          dnxSMSetzen(!dnxSMStand());
          try{ dnxRowAnordnen(); }catch(eR){}
        });
        frisch = true;
      }
      if(row){
        /* in die Reihe - sie sortiert sich selbst alphabetisch */
        if(b.parentNode !== row){ row.appendChild(b); frisch = true; }
      }else if(panel && b.parentNode !== panel){
        var anker = document.getElementById("dnx-weather-launch") || document.getElementById("dnx-styler-launch");
        if(anker && anker.parentNode === panel){ panel.insertBefore(b, anker); }
        else { panel.appendChild(b); }
        frisch = true;
      }
      dnxSMKnopfText();
      if(frisch){ try{ dnxRowAnordnen(); }catch(eA){} }
    }catch(e){}
  }
  function dnxSMKnopfText(){
    var b = document.getElementById("dnx-master-smeternadel");
    if(!b) return;
    var an = dnxSMStand();
    /* v3.125: genau wie die Nachbarn ("Slots: An", "DNX DAB: Aus").
       Absichtlich KEIN Emoji - das wuerde den Knopf bei der alphabetischen
       Sortierung nach vorn ziehen (wie bei Magnetfeld und ISS zu sehen). */
    b.textContent = "S-Meter: " + (an ? "An" : "Aus");
    try{ b.title = "S-Meter " + (an ? "an" : "aus"); }catch(eT){}
    try{
      b.style.setProperty("background", an ? "#1f8f52" : "#666666", "important");
      b.style.setProperty("color", an ? "#f2fff8" : "#ffffff", "important");
    }catch(e){}
  }

  /* ---- Funkgeraet (President George II) -----------------------------------
     Der Schalter haengt am Plugin selbst: window.dnxGeorge2.zeige(an) blendet
     das Geraet ein und aus, stand().offen sagt, wie es gerade steht. Damit
     gibt es keinen zweiten Speicher, der auseinanderlaufen koennte. */
  function dnxFunkStand(){
    try{
      if(!window.dnxGeorge2 || !window.dnxGeorge2.stand){ return null; }
      var s = window.dnxGeorge2.stand();
      if(!s){ return null; }
      return !!s.offen;
    }catch(e){ return null; }
  }
  function dnxFunkSetzen(an){
    try{
      if(window.dnxGeorge2 && window.dnxGeorge2.geraetAn && window.dnxGeorge2.geraetAus){
        return an ? window.dnxGeorge2.geraetAn(1) : window.dnxGeorge2.geraetAus(1);
      }
      if(!window.dnxGeorge2 || !window.dnxGeorge2.zeige){ return false; }
      window.dnxGeorge2.zeige(!!an);
      return true;
    }catch(e){ return false; }
  }
  /* Zweites Geraet */
  function dnxFunk2Stand(){
    try{
      if(window.dnxGeorge2 && window.dnxGeorge2.stand){ return !!window.dnxGeorge2.stand().aeOffen; }
      if(window.dnxFunkgeraete && window.dnxFunkgeraete.stand){
        var g = window.dnxFunkgeraete.stand().geraete;
        return (g && g[1]) ? !!g[1].offen : null;
      }
      return null;
    }catch(e){ return null; }
  }
  function dnxFunk2Setzen(an){
    try{
      if(window.dnxGeorge2 && window.dnxGeorge2.geraetAn){
        return an ? window.dnxGeorge2.geraetAn(2) : window.dnxGeorge2.geraetAus(2);
      }
      if(window.dnxFunkgeraete && window.dnxFunkgeraete.zeige){
        window.dnxFunkgeraete.zeige(1, !!an); return true;
      }
      return false;
    }catch(e){ return false; }
  }
  /* Drittes Geraet */
  function dnxFunk3Stand(){
    try{
      if(window.dnxGeorge2 && window.dnxGeorge2.stand){
        var s = window.dnxGeorge2.stand();
        if(s && typeof s.p3Offen === "boolean"){ return !!s.p3Offen; }
      }
      if(window.dnxFunkgeraete && window.dnxFunkgeraete.stand){
        var g = window.dnxFunkgeraete.stand().geraete;
        return (g && g[2]) ? !!g[2].offen : null;
      }
      return null;
    }catch(e){ return null; }
  }
  function dnxFunk3Setzen(an){
    try{
      if(window.dnxGeorge2 && window.dnxGeorge2.geraetAn){
        return an ? window.dnxGeorge2.geraetAn(3) : window.dnxGeorge2.geraetAus(3);
      }
      if(window.dnxFunkgeraete && window.dnxFunkgeraete.zeige){
        window.dnxFunkgeraete.zeige(2, !!an); return true;
      }
      return false;
    }catch(e){ return false; }
  }

  /* Knopf in der Werkzeugreihe - genau wie S-Meter / AF / Slots.
     Er zeigt und schaltet das Geraet, das im Styler gewaehlt ist:
     "Funkgeraet 1" oder "Funkgeraet 2". Ein Klick wechselt nur den Ein/Aus-
     Zustand, das Mausrad und der Styler-Haken waehlen das Geraet. */
  /* ---- Zwei eigene Schalter statt eines Durchlauf-Knopfes ----------------
     Die Klickfolge (1 -> 2 -> beide -> aus) war zu verwirrend: ein Knopf mit
     vier Zustaenden und wechselndem Text. Jetzt hat JEDES Funkgeraet seinen
     eigenen Schalter:
        "Funkgerät 1: An/Aus"  und  "Funkgerät 2: An/Aus".
     Gruen = sichtbar, grau = zu. Beide gruen = beide gleichzeitig (verschiedene
     Kanaele im selben Profil). Kein versteckter Zustand mehr.
     Mausrad auf einem der beiden Schalter tauscht weiter 1 <-> 2. */
  function dnxFunkKnopfBauen(id, nr){
    var row = document.getElementById("dnx-master-tool-row");
    var panel = document.getElementById("openwebrx-panel-receiver");
    var b = document.getElementById(id);
    if(!b){
      b = document.createElement("button");
      b.type = "button";
      b.id = id;
      b.setAttribute("data-dnx-funk", nr);
      b.__dnxFunkNr = nr;
      b.addEventListener("click", function(ev){
        if(ev && ev.preventDefault){ ev.preventDefault(); }
        if(ev && ev.stopPropagation){ ev.stopPropagation(); }
        dnxFunkSchalten(nr);
      });
      /* Der Klick wird auf dieser Seite in der Fangphase geschluckt - das
         Zeiger-Ende kommt immer an, deshalb haengt der Schalter auch dort. */
      b.addEventListener("pointerup", function(ev){ dnxFunkSchalten(nr); });
      /* v7.1: Hier hing zusaetzlich ein zweiter Rad-Handler. Ein echter Radschritt
         lief damit ZWEIMAL durch den Tausch (einmal Fangphase am Fenster, einmal
         hier) - netto passierte nichts oder das Gegenteil. Jetzt gibt es nur noch
         den einen Haken unten, mit Sperre je Geste. */
    }
    if(row){
      if(b.parentNode !== row){ row.appendChild(b); }
    }else if(panel && b.parentNode !== panel){
      var ankerB = document.getElementById("dnx-weather-launch") || document.getElementById("dnx-styler-launch");
      if(ankerB && ankerB.parentNode === panel){ panel.insertBefore(b, ankerB); }
      else { panel.appendChild(b); }
    }
    return b;
  }
  /* ein Geraet umschalten - das andere bleibt unberuehrt */
  var _funkLetzteSchaltung = 0;
  var _funkLetzterTausch = 0;
  function dnxFunkSchalten(nr){
    var jetzt = Date.now();
    /* click und pointerup kommen beide an: nur einer zaehlt */
    if(jetzt - _funkLetzteSchaltung < 350){ return; }
    _funkLetzteSchaltung = jetzt;
    var s = String(nr);
    var ist = (s === "3") ? dnxFunk3Stand() : ((s === "2") ? dnxFunk2Stand() : dnxFunkStand());
    var ziel = (ist !== true);
    if(s === "3"){ dnxFunk3Setzen(ziel); }
    else if(s === "2"){ dnxFunk2Setzen(ziel); }
    else { dnxFunkSetzen(ziel); }
    if(ziel){ dnxFunkAktivNur(s); }
    dnxFunkKnopfText();
    try{ dnxRowAnordnen(); }catch(eR){}
  }
  /* Mausrad: Geraet tauschen (1 -> 2 -> 3 -> 1) - es bleibt immer nur EINES zu sehen */
  function dnxFunkTauschen(){
    var akt = dnxFunkAktiv();
    var ziel = (akt === "1") ? "2" : (akt === "2" ? "3" : "1");
    dnxFunkSetzen(ziel === "1");
    dnxFunk2Setzen(ziel === "2");
    dnxFunk3Setzen(ziel === "3");
    dnxFunkAktivNur(ziel);
    dnxFunkKnopfText();
    try{ dnxRowAnordnen(); }catch(eR2){}
  }

  function dnxFunkKnopf(){
    try{
      var row = document.getElementById("dnx-master-tool-row");
      var panel = document.getElementById("openwebrx-panel-receiver");
      if(!row && !panel) return;
      dnxFunkKnopfBauen("dnx-master-funkgeraet", "1");
      dnxFunkKnopfBauen("dnx-master-funkgeraet2", "2");
      dnxFunkKnopfBauen("dnx-master-funkgeraet3", "3");
      window.__dnxFunkSync = dnxFunkKnopfText;
      window.dnxFunkKnopfAuffrischen = dnxFunkKnopfText;
      /* Einmal-Haken auf Fenster-Ebene: die Seite faengt Klick und Rad in der
         Fangphase ab, bevor sie die Knoepfe erreichen. */
      if(!window.__dnxFunkHaken){
        window.__dnxFunkHaken = 1;
        document.addEventListener("pointerup", function(ev){
          var t2 = (ev.target && ev.target.closest) ? ev.target.closest("[data-dnx-funk]") : null;
          if(t2){ dnxFunkSchalten(t2.getAttribute("data-dnx-funk")); }
        }, true);
        window.addEventListener("wheel", function(ev){
          var t3 = (ev.target && ev.target.closest) ? ev.target.closest("[data-dnx-funk]") : null;
          if(!t3){ return; }
          if(ev.preventDefault){ ev.preventDefault(); }
          /* Eine Rastung des Mausrads schickt mehrere wheel-Ereignisse - nur das
             erste zaehlt, sonst tauscht es mehrfach hin und her. */
          var jetzt2 = Date.now();
          if(jetzt2 - _funkLetzterTausch < 260){ return; }
          _funkLetzterTausch = jetzt2;
          dnxFunkTauschen();
        }, { capture: true, passive: false });
      }
      dnxFunkKnopfText();
      try{ dnxRowAnordnen(); }catch(eA){}
    }catch(e){}
  }
  function dnxFunkAktiv(){
    try{
      if(window.dnxGeorge2 && window.dnxGeorge2.aktiv){ return window.dnxGeorge2.aktiv(); }
      var v = localStorage.getItem("dnx_ae6290_aktiv") || "1";
      return (v === "2" || v === "3") ? v : "1";
    }catch(e){ return "1"; }
  }
  function dnxFunkAktivSetzen(nr){
    var s = String(nr);
    var z = (s === "2" || s === "3") ? s : "1";
    try{
      if(window.dnxGeorge2 && window.dnxGeorge2.geraetAn){ window.dnxGeorge2.geraetAn(z); return; }
    }catch(e){}
    try{ localStorage.setItem("dnx_ae6290_aktiv", z); }catch(e2){}
  }
  /* Nur MERKEN, welches Geraet gemeint ist - ohne etwas ein- oder
     auszuschalten. Sonst wuerde "alles aus" das Geraet gleich wieder
     einschalten, weil geraetAn() auch einschaltet. */
  function dnxFunkAktivNur(nr){
    var s = String(nr);
    nr = (s === "2" || s === "3") ? s : "1";
    try{
      if(window.dnxGeorge2 && window.dnxGeorge2.nurAktiv){ window.dnxGeorge2.nurAktiv(nr); return nr; }
    }catch(e){}
    try{ localStorage.setItem("dnx_ae6290_aktiv", nr); }catch(e2){}
    return nr;
  }
  function dnxFunkKnopfText(){
    var paare = [["dnx-master-funkgeraet", "1", dnxFunkStand()],
                 ["dnx-master-funkgeraet2", "2", dnxFunk2Stand()],
                 ["dnx-master-funkgeraet3", "3", dnxFunk3Stand()]];
    for(var i = 0; i < paare.length; i++){
      var b = document.getElementById(paare[i][0]);
      if(!b){ continue; }
      var nr = paare[i][1], an = paare[i][2];
      b.textContent = "Funkger\u00e4t " + nr + ": " + (an === null ? "\u2013" : (an ? "An" : "Aus"));
      try{
        b.title = "Funkger\u00e4t " + nr + " " + (an ? "an" : "aus")
          + " \u00b7 Klick schaltet nur dieses Ger\u00e4t \u00b7 Mausrad tauscht 1 \u21c4 2 \u21c4 3";
      }catch(eT){}
      try{
        b.style.setProperty("background", an ? "#1f8f52" : "#666666", "important");
        b.style.setProperty("color", an ? "#f2fff8" : "#ffffff", "important");
      }catch(e){}
    }
  }

  function dnxSMeter(){
    try{
      dnxSMKnopf();
      var boxAlt = document.getElementById("dnx-smeter-box");
      if(!dnxSMStand()){
        if(boxAlt) boxAlt.style.setProperty("display", "none", "important");
        return;
      }
      if(boxAlt) boxAlt.style.setProperty("display", "", "important");
      var box = boxAlt;
      if(!box){
        var leiste = document.querySelector(".webrx-top-bar");
        if(!leiste) return;
        box = document.createElement("div");
        box.id = "dnx-smeter-box";
        box.innerHTML = "";
        dnxSMeterInhalt(box);
        leiste.appendChild(box);
        if(getComputedStyle(leiste).position === "static"){ leiste.style.position = "relative"; }
        /* Die Kopfzeile ist 67 px hoch und mit overflow:hidden versehen - sonst
           waeren die unteren 35 px des Messwerks abgeschnitten. */
        if(getComputedStyle(leiste).overflow === "hidden"){ leiste.style.overflow = "visible"; }
        window.addEventListener("resize", dnxSMeterAusrichten);
      }
      if(box.__dnxModell !== dnxSMSignatur()){ dnxSMeterInhalt(box); }
      dnxSMeterAusrichten();
      /* Haken in die Kern-Routine: unser Lauf wird nach dem Original ausgefuehrt */
      if(typeof window.setSmeterRelativeValue === "function" && !window.setSmeterRelativeValue.__dnxHaken){
        var orig = window.setSmeterRelativeValue;
        var neu = function(v){ try{ orig.apply(this, arguments); }catch(eA){} try{ dnxSMeterZeigen(v); }catch(eB){} };
        neu.__dnxHaken = 1;
        window.setSmeterRelativeValue = neu;
      }
    }catch(eSM){}
  }

  function dnxSMeterAusrichten(){
    try{
      var box = document.getElementById("dnx-smeter-box");
      if(!box) return;
      var leiste = box.parentElement;
      if(!leiste) return;
      var hilfe = null;
      var knopf = document.querySelectorAll(".openwebrx-main-buttons a.button, .openwebrx-main-buttons .button");
      for(var i = 0; i < knopf.length; i++){
        if(/help/i.test((knopf[i].textContent || "").trim())){ hilfe = knopf[i]; break; }
      }
      var lr = leiste.getBoundingClientRect();
      var dx = dnxSMLesen(DNX_SM_SX), dy = dnxSMLesen(DNX_SM_SY);
      var rechts;
      if(hilfe){
        var hr = hilfe.getBoundingClientRect();
        rechts = lr.right - hr.left + 8 - dx;
      }else{
        rechts = 400 - dx;
      }
      box.style.setProperty("right", Math.max(0, Math.round(rechts)) + "px", "important");
      box.style.setProperty("top", Math.round(dy) + "px", "important");
    }catch(eSM2){}
  }

  /* v3.126: baut den Inhalt der Box passend zum gewaehlten Modell */
  function dnxSMeterInhalt(box){
    var m = dnxSMModell();
    box.innerHTML = "";
    if(m.art === "lcd"){
      dnxSMLcdBauen(box, m);
    }else{
    var fl = document.createElement("img");
    fl.id = "dnx-smeter-flaeche";
    fl.src = m.flaeche;
    fl.alt = "";
    box.appendChild(fl);
    if(m.art === "bild"){
      /* v7.1: gezeichneter senkrechter Balken statt verschobenem Nadelbild */
      var nd = document.createElement("div");
      nd.id = "dnx-smeter-nadel";
      box.appendChild(nd);
    }else if(m.art === "zeiger"){
      var zb = document.createElement("div");
      zb.id = "dnx-smeter-zeigerbox";
      var zg = document.createElement("div");
      zg.id = "dnx-smeter-zeiger";
      zg.style.setProperty("width", m.zeiger.b + "px", "important");
      zg.style.setProperty("height", m.zeiger.laenge + "px", "important");
      zg.style.setProperty("left", Math.round(DNX_SM_DPX - m.zeiger.b / 2) + "px", "important");
      zg.style.setProperty("top", Math.round(DNX_SM_DPY - m.zeiger.laenge) + "px", "important");
      zg.style.setProperty("background", m.zeiger.farbe, "important");
      zg.style.setProperty("box-shadow", m.zeiger.schein, "important");
      zb.appendChild(zg);
      box.appendChild(zb);
    }else if(m.art === "bogen"){
      var bg = document.createElement("div");
      bg.id = "dnx-smeter-balken";
      bg.style.setProperty("left", "0px", "important");
      bg.style.setProperty("top", "0px", "important");
      bg.style.setProperty("width", "238px", "important");
      bg.style.setProperty("height", "66px", "important");
      bg.style.setProperty("background-image", 'url("' + m.segmente + '")', "important");
      var keil0 = "conic-gradient(from " + (-m.bogen.winkel) + "deg at " + m.bogen.dpX + "px "
                + m.bogen.dpY + "px, #000 0deg 0deg, transparent 0deg)";
      bg.style.setProperty("-webkit-mask-image", keil0, "important");
      bg.style.setProperty("mask-image", keil0, "important");
      box.appendChild(bg);
    }else{
      var bk = document.createElement("div");
      bk.id = "dnx-smeter-balken";
      bk.style.setProperty("left", m.balken.x + "px", "important");
      bk.style.setProperty("top", m.balken.y + "px", "important");
      bk.style.setProperty("width", m.balken.b + "px", "important");
      bk.style.setProperty("height", m.balken.h + "px", "important");
      bk.style.setProperty("background-image", m.balken.farbe, "important");
      bk.style.setProperty("-webkit-mask-image", m.balken.maske, "important");
      bk.style.setProperty("mask-image", m.balken.maske, "important");
      box.appendChild(bk);
    }
    }
    var tx = document.createElement("div");
    tx.id = "dnx-smeter-text";
    tx.textContent = "--";
    box.appendChild(tx);
    box.__dnxModell = dnxSMSignatur();
  }

  function dnxSMeterZeigen(anteil){
    if(typeof anteil !== "number" || isNaN(anteil)) return;
    if(anteil < 0) anteil = 0;
    if(anteil > 1) anteil = 1;
    var m = dnxSMModell();
    if(m.art === "bild"){
      var nadel = document.getElementById("dnx-smeter-nadel");
      if(nadel){
        /* Mitte der Skala anfahren; der Balken ist 3 px breit -> halbe Breite abziehen */
        var mitte = m.x0 + anteil * (m.x1 - m.x0);
        /* z ist der Abstand vom linken Rand des 11-px-Streifens zur Nadelmitte
           (5,5 bei der alten Bild-Nadel). Der gezeichnete Balken ist 3 px breit,
           seine eigene Mitte liegt bei 1,5 - deshalb so rechnen, dass die
           Nadelmitte auf denselben Punkt kommt wie vorher. */
        nadel.style.transform = "translateX(" + (mitte - 1.5 - (m.z - 5.5)).toFixed(1) + "px)";
      }
    }else if(m.art === "zeiger"){
      var zg = document.getElementById("dnx-smeter-zeiger");
      if(zg){
        var w = -m.zeiger.winkel + 2 * m.zeiger.winkel * anteil;
        zg.style.transform = "rotate(" + w.toFixed(2) + "deg)";
      }
    }else if(m.art === "lcd"){
      var segs = document.querySelectorAll("#dnx-smeter-lcd .dnx-sm-seg");
      var hell = dnxSMFarbe().hex;
      var aktiv = anteil * DNX_SM_LCD_GEO[m.form].n;
      var schein = "0 0 7px " + dnxSMRgba(hell, 0.55);
      for(var i = 0; i < segs.length; i++){
        var an = ((i + 1) <= aktiv + 1e-6) ? 1 : 0;
        if(segs[i].__dnxAn === an) continue;
        segs[i].__dnxAn = an;
        segs[i].style.setProperty("background", an ? hell : dnxSMRgba(hell, 0.13), "important");
        segs[i].style.setProperty("box-shadow", an ? schein : "none", "important");
      }
    }else if(m.art === "bogen"){
      var bg = document.getElementById("dnx-smeter-balken");
      if(bg){
        var grad = (2 * m.bogen.winkel * anteil).toFixed(1);
        var keil = "conic-gradient(from " + (-m.bogen.winkel) + "deg at " + m.bogen.dpX + "px "
                 + m.bogen.dpY + "px, #000 0deg " + grad + "deg, transparent " + grad + "deg)";
        bg.style.setProperty("-webkit-mask-image", keil, "important");
        bg.style.setProperty("mask-image", keil, "important");
      }
    }else{
      var bk = document.getElementById("dnx-smeter-balken");
      if(bk){
        var rest = (100 - anteil * 100).toFixed(1);
        var klammer = "inset(0 " + rest + "% 0 0)";
        bk.style.clipPath = klammer;
        bk.style.setProperty("-webkit-clip-path", klammer, "important");
      }
    }
    var txt = document.getElementById("dnx-smeter-text");
    if(txt){
      var db = document.getElementById("openwebrx-smeter-db");
      var wert = db ? (db.textContent || "").trim() : "";
      if(wert) txt.textContent = wert;
    }
  }

  /* v3.117: Bandplan besser lesbar machen.
     Der Core (lib/Bandplan.js) kennt vier Bandarten mit sehr dunklen Farben.
     Baender OHNE Typ bekommen bei ihm ein traubes Grau (#808080) - die sind
     hier nachher blau und damit vom Rauschen zu unterscheiden. */
  function dnxBandplan(){
    try{
      var bp = window.bandplan;
      if(!bp){ return; }
      if(!bp.__dnxFarben){
        bp.colors = {
          hamradio:  "#00b04a",
          broadcast: "#3355e0",
          public:    "#b03ce0",
          service:   "#e03a3a"
        };
        bp.__dnxFarben = 1;
      }
      try{ dnxTextSchwarz(bp.ctx); }catch(eC){}
      if(window.Bandplan && !window.Bandplan.prototype.__dnxFarbe){
        var alt = window.Bandplan.prototype.getColor;
        window.Bandplan.prototype.__dnxFarbe = alt;
        window.Bandplan.prototype.getColor = function(type){
          if(!type || !(type in this.colors)){ return "#5a7fd0"; }
          return alt.call(this, type);
        };
      }
      if(window.Bandplan && !window.Bandplan.prototype.__dnxSchrift){
        var zeichnen = window.Bandplan.prototype.draw;
        window.Bandplan.prototype.draw = function(){
          var erg = zeichnen.apply(this, arguments);
          try{ dnxTextSchwarz(this.ctx); }catch(eC){}
          return erg;
        };
        window.Bandplan.prototype.__dnxSchrift = 1;
      }
    }catch(eBp){}
  }

  function dnxFftWache(){
    try{
      if(!dnxFftInstall.on){
        dnxFftInstall.on = 1;
        var schnell = 0;
        setInterval(function(){
          schnell++;
          try{
            dnxSpekInstall();      /* Merker __dnxSpekEigen zuerst auffrischen */
            dnxBandplan();
            dnxSMeter();
            dnxFunkKnopf();
            dnxBgSetzen();
            if(!fftCtx || !fftCtx.__dnxFillHook){ dnxFftInstall(); }
            if(fftCtx && fftCtx.__dnxFillHook && !fftCtx.__dnxSitzt){
              dnxFftSetze();
              fftCtx.__dnxSitzt = 1;
            }
          }catch(e){}
          if(schnell === 57 && !(fftCtx && fftCtx.__dnxFillHook)){ dnxFftSetze(); }
        }, (schnell < 60) ? 700 : 5000);
      }
    }catch(e){}
  }

  function dnxWfReset(){
    try{
      localStorage.setItem(WF_KEY, "default");
      localStorage.setItem(FFT_KEY, "original");
      localStorage.setItem(WF_ON_KEY, "an");
    }catch(e){}
    dnxAnKlasse();
    dnxFftAnSetze(false);
    if(wfEls.sel){ wfEls.sel.value = "default"; }
    if(wfEls.fft){ wfEls.fft.value = "original"; }
    dnxWfApply("default");
    dnxFftApply();
  }
  function dnxWfTick(){
    dnxWfReg();
    dnxAnTick();
    if(window.spectrum && spectrum.ctx && dnxFftId() !== "original"){ dnxFftInstall(); }
    dnxWfState();
  }
  function dnxWfBoot(){
    dnxWfReg();
    dnxAnBoot();
    if(dnxWfGespeichert()){ dnxWfApply(dnxWfId()); }
    if(dnxFftId() !== "original"){ dnxFftApply(); }
    dnxWfState();
  }
  /* ---- v40: Schalter fuer Wasserfall und Spektrum (nur im Browser) ----
     Wasserfall aus  -> Body-Klasse dnx-wf-aus; das eigene Stylesheet dnx-an-sheet
     blendet nur die Wasserfall-Zeichenflaechen aus (Frequenzleiste, Buchungen und
     Bedienfelder bleiben, wo sie sind). Spektrum an/aus -> ruft das Original
     UI.toggleSpectrum(on); der Zustand liegt wie beim Original-Knopf in
     ui_spectrum, damit unser Schalter und der Original-Knopf synchron bleiben.
     Keine Core-Datei wird angefasst. */
  var WF_ON_KEY = "dnx_styler_wf_an";

  /* ---- 3D-Wasserfall (dnx_3dtool): Ansicht 2D / 3D / BEIDE ---- */
  var M3D_KEY = "dnx_3dtool";
  function dnx3dLesen(){
    var o = {};
    try{ o = JSON.parse(localStorage.getItem(M3D_KEY) || "{}") || {}; }catch(e){ o = {}; }
    var m = "std";
    if(o.viewMode === "3d" || o.viewMode === "both"){ m = o.viewMode; }
    else if(o.enabled === true){ m = "3d"; }
    if(o.enabled === false){ m = "std"; }
    return { mode: m, flip: o.splitFlip ? 1 : 0 };
  }
  function dnx3dSetzen(mode, flip){
    if(mode !== "std" && mode !== "3d" && mode !== "both"){ return false; }
    try{
      var o = {};
      try{ o = JSON.parse(localStorage.getItem(M3D_KEY) || "{}") || {}; }catch(e){ o = {}; }
      o.viewMode = mode;
      o.enabled = (mode !== "std");
      o.layoutVersion = 2;
      if(flip === 0 || flip === 1){ o.splitFlip = !!flip; }
      localStorage.setItem(M3D_KEY, JSON.stringify(o));
    }catch(e){}
    var versuche = 0;
    function anwenden(){
      var P = null;
      try{ P = (window.Plugins && Plugins.dnx_3dtool) || null; }catch(e){ P = null; }
      if(P && typeof P.setMode === "function" && P.settings){
        try{
          if(flip === 0 || flip === 1){ P.settings.splitFlip = !!flip; }
          P.setMode(mode, true);
          if(typeof P._layoutMode === "function"){ P._layoutMode(); }
        }catch(e2){}
        return true;
      }
      return false;
    }
    if(anwenden()){ return true; }
    var t = setInterval(function(){
      versuche++;
      if(anwenden() || versuche > 60){ clearInterval(t); }
    }, 250);
    return true;
  }
