      var inRcv = !!(rp && rp.contains(cand));
      try{ r = cand.getBoundingClientRect(); }catch(e2){ continue; }
      if(inRcv){ add(cand); continue; }
      if(r.width >= 30 && r.height >= 2 && r.height <= 90) add(cand);
