      var host = (probe && probe.parentElement) ? probe.parentElement : null;
      var s = "v3.5 | overlay=" + (overlay ? "ja" : "NEIN") + " | griff=" + (probe ? "ja" : "NEIN") + " | host=" + (host ? (host.id || host.className || host.tagName) : "-");
      var wins = dnxWindows(true);
