/* [DNX-EXTRAS-START] Audio-Filter, DX-Cluster und Sonne.
   Haengt am Styler, weil nur dieser bei jedem Aufruf frisch geladen wird. */
(function () {
    if (window.__dnxExtrasStart) { return; }
    window.__dnxExtrasStart = true;

    var GEWUENSCHT = ['plugin-button-audio_filter', 'plugin-button-dxcluster'];

    // Wirklich sichtbar? Es reicht nicht, das Element selbst zu fragen -
    // das Panel meldet "block", sein Elternelement ist aber versteckt.
    function sichtbar(el) {
        if (!el) { return false; }
        var r = el.getBoundingClientRect();
        if (r.width <= 0 && r.height <= 0) { return false; }
        var p = el;
        while (p && p !== document.body && p !== document.documentElement) {
            var s = window.getComputedStyle(p);
            if (s.display === 'none' || s.visibility === 'hidden' || s.opacity === '0') { return false; }
            p = p.parentElement;
        }
        return true;
    }

    // Zieht einen Knopf in die DNX-Werkzeugleiste um.
    // Die DNX-Knoepfe tragen keine Klasse - ihr Aussehen kommt allein aus dem
    // Leisten-CSS. Die Kern-Klasse muss also weg, sonst passt nichts zusammen.
    function umziehen(k) {
        if (k.__dnxUmgezogen) { return true; }
        var reihe = document.getElementById('dnx-master-tool-row');
        if (!reihe) { return false; }
        k.className = '';
        k.style.cssText = '';
        var vorbild = document.getElementById('dnx-ex-solar') || reihe.children[0];
        if (vorbild && vorbild !== k) {
            var s = window.getComputedStyle(vorbild);
            try {
                k.style.setProperty('background', s.backgroundColor, 'important');
                k.style.setProperty('color', s.color, 'important');
                k.style.height = s.height;
                k.style.lineHeight = s.lineHeight;
                k.style.padding = s.padding;
                k.style.fontSize = s.fontSize;
                k.style.fontFamily = s.fontFamily;
                k.style.boxSizing = s.boxSizing;
                k.style.display = s.display;
                k.style.alignItems = s.alignItems;
                k.style.justifyContent = s.justifyContent;
                k.style.border = s.border;
                k.style.borderRadius = s.borderRadius;
                k.style.cursor = 'pointer';
            } catch (eS) { }
        }
        k.__dnxUmgezogen = true;
        reihe.appendChild(k);
        return true;
    }

    // Alle gewuenschten Knoepfe finden - egal wo sie gerade stecken.
    function einsammeln() {
        var fertig = true;
        for (var i = 0; i < GEWUENSCHT.length; i++) {
            var k = document.getElementById(GEWUENSCHT[i]);
            if (!k) { fertig = false; continue; }          // Knopf gibt es noch nicht
            if (k.__dnxUmgezogen) { continue; }            // schon umgezogen
            if (sichtbar(k)) { continue; }                 // ist schon zu sehen
            if (!umziehen(k)) { fertig = false; }          // Werkzeugleiste noch nicht da
        }
        return fertig;
    }

    function bruecke() {
        try {
            if (typeof Plugins === 'undefined') { return false; }
            if (typeof window.Plugin === 'undefined') { window.Plugin = Plugins; }
            if (typeof Plugins.addButton === 'function' && !Plugins.__dnxBruecke) {
                var orig = Plugins.addButton;
                Plugins.addButton = function (id, titel, handler, farbe) {
                    var k = orig.apply(this, arguments);
                    try {
                        if (k && k.id && GEWUENSCHT.indexOf(k.id) >= 0) { umziehen(k); }
                    } catch (eA) { }
                    return k;
                };
                Plugins.__dnxBruecke = true;
            }
            return true;
        } catch (e) { return false; }
    }

    function start() {
        if (!bruecke()) { return false; }
        try { Plugins.load('audio_filter'); } catch (e1) { }
        try { Plugins.load('dxcluster'); } catch (e2) { }
        try {
            if (!document.getElementById('dnx-extras-script')) {
                var s = document.createElement('script');
                s.id = 'dnx-extras-script';
                s.src = 'static/plugins/receiver/dnx_extras.js?v=' + Date.now();
                (document.head || document.documentElement).appendChild(s);
            }
        } catch (e3) { }
        return true;
    }

    var n = 0;
    var t = setInterval(function () {
        n++;
        var fertig = false;
        try { fertig = start() && einsammeln(); } catch (e4) { }
        if (fertig || n > 60) { clearInterval(t); }   // max. ca. 2 Minuten
    }, 700);
})();
/* [DNX-EXTRAS-ENDE] */

/* DNX_LEISTE_OBEN_START */
(function(){
  if(window.__dnxLeisteOben) return;
  window.__dnxLeisteOben = true;
  function holen(){
    var row  = document.getElementById("dnx-master-tool-row");
    var body = document.getElementById("dnx-receiver-overlay-body");
    if(!row || !body) return false;
    /* Leiste gehoert ins Receiver-Panel, direkt vor die Frequenzanzeige
       (Zustand wie auf 113) - nicht in den Overlay-Koerper. */
    try{
      var recv = document.getElementById("openwebrx-panel-receiver");
      if(recv){
        var frq = recv.querySelector(".webrx-actual-freq-holder") ||
                  recv.querySelector(".webrx-actual-freq");
        var ank = frq;
        while(ank && ank.parentNode && ank.parentNode !== recv){ ank = ank.parentNode; }
        if(row.parentElement !== recv){
          if(ank && ank.parentNode === recv) recv.insertBefore(row, ank);
          else recv.insertBefore(row, recv.firstChild);
        }
      }
      row.style.flex = "0 0 auto";
      row.style.position = "static";
      row.style.top = "auto";
      row.style.bottom = "auto";
      row.style.zIndex = "5";
    }catch(err){}
    return true;
  }
  function tick(){ try{ holen(); }catch(err){} }
  tick();
  setInterval(tick, 1200);
  window.addEventListener("load", function(){
    setTimeout(tick, 300); setTimeout(tick, 1200); setTimeout(tick, 3500);
  });
})();
/* DNX_LEISTE_OBEN_END */


/* ---------- DNX_LEISTE_SICHTBAR_START ---------- */
(function(){
  if(window.__dnxLeisteSichtbar) return;
  window.__dnxLeisteSichtbar = true;
  function korrigiere(){
    var leiste = document.getElementById("dnx-master-tool-row");
    var body   = document.getElementById("dnx-receiver-overlay-body");
    if(!leiste || !body) return false;
    /* Leiste gehoert ins Receiver-Panel (Zustand wie auf 113). */
    var recv2 = document.getElementById("openwebrx-panel-receiver");
    if(recv2 && leiste.parentElement !== recv2){
      var frq2 = recv2.querySelector(".webrx-actual-freq-holder") ||
                 recv2.querySelector(".webrx-actual-freq");
      var ank2 = frq2;
      while(ank2 && ank2.parentNode && ank2.parentNode !== recv2){ ank2 = ank2.parentNode; }
      if(ank2 && ank2.parentNode === recv2) recv2.insertBefore(leiste, ank2);
      else recv2.insertBefore(leiste, recv2.firstChild);
    }
    var s = leiste.style;
    s.setProperty("position","static","important");
    s.setProperty("top","auto","important");
    s.setProperty("bottom","auto","important");
    s.setProperty("z-index","5","important");
    s.setProperty("max-height","none","important");
    s.setProperty("overflow-y","auto","important");
    s.setProperty("flex","0 0 auto","important");
    s.setProperty("background","#0b1f16","important");
    body.style.setProperty("overflow-y","auto","important");

    /* DNX_OVERLAY_Z_START
       Overlay lag mit z-index 2147483647 ueber allen Werkzeugfenstern
       (QRM usw. 2147483645) -> Fenster nicht verschiebbar. */
    try{
      var ov = document.getElementById("dnx-receiver-overlay");
      if(ov) ov.style.setProperty("z-index","2147483000","important");
    }catch(e){}
    /* DNX_OVERLAY_Z_END */

    return true;
  }
  function tick(){ try{ korrigiere(); }catch(e){} }
  tick();
  setInterval(tick, 1500);
  window.addEventListener("load", function(){
    setTimeout(tick, 300); setTimeout(tick, 1500);
  });
})();
/* ---------- DNX_LEISTE_SICHTBAR_END ---------- */
